window.QUESTIONS = [{"id": 1, "chapter": "习近平强军思想", "stem": "根据习近平强军思想，党在新时代的强军目标中关于人民军队建设的规范表述是？", "options": {"A": "听党指挥、能打胜仗、作风优良", "B": "政治合格、军事过硬、纪律严明", "C": "绝对忠诚、保障有力、作风过硬", "D": "听党指挥、科技领先、依法治军"}, "answer": "A", "explanation": "规范表述是建设一支听党指挥、能打胜仗、作风优良的人民军队。其余选项混入了相关但不属于强军目标三项核心内容的表述。"}, {"id": 2, "chapter": "习近平强军思想", "stem": "下列哪一项准确反映了国防和军队现代化新“三步走”战略安排？", "options": {"A": "到2027年基本实现机械化；到2035年全面实现国防和军队现代化；到本世纪中叶建成世界一流军队", "B": "到2027年实现建军一百年奋斗目标；到2035年基本实现国防和军队现代化；到本世纪中叶把人民军队全面建成世界一流军队", "C": "到2027年实现建军一百年奋斗目标；到2035年把人民军队全面建成世界一流军队；到本世纪中叶全面实现国防和军队现代化", "D": "到2027年基本实现国防和军队现代化；到2035年实现建军一百年奋斗目标；到本世纪中叶建成机械化信息化军队"}, "answer": "B", "explanation": "新“三步走”以2027年、2035年和本世纪中叶为近、中、远三个节点，依次对应实现建军一百年奋斗目标、基本实现国防和军队现代化、全面建成世界一流军队。"}, {"id": 3, "chapter": "习近平强军思想", "stem": "关于习近平强军思想科学体系的总体结构，下列对应关系正确的是？", "options": {"A": "以强军目标为牵引，以“五个坚持”为主干，以“十一个明确”为精髓", "B": "以“十一个明确”为牵引，以强军目标为主干，以“五个坚持”为精髓", "C": "以强军目标为牵引，以“十一个明确”为主干，以“五个坚持”为精髓", "D": "以使命任务为牵引，以“五个更加注重”为主干，以强军战略布局为精髓"}, "answer": "C", "explanation": "习近平强军思想以强军目标为牵引，以“十一个明确”为主干，以“五个坚持”为精髓。“十一个明确”集中体现主要内容，“五个坚持”体现军事观和方法论，三者不能互换。"}, {"id": 4, "chapter": "习近平强军思想", "stem": "按“十一个明确”的现行排列顺序，第一项和最后一项分别是？", "options": {"A": "强国必须强军——作风优良是我军鲜明特色和政治优势", "B": "党在新时代的强军目标——军民融合发展是兴国之举、强军之策", "C": "军队是要准备打仗的——依法治军是我们党建军治军基本方式", "D": "党对人民军队的绝对领导——作风优良是我军鲜明特色和政治优势"}, "answer": "D", "explanation": "现行“十一个明确”以党对人民军队的绝对领导开篇，以作风优良收束。A项首项、B项两端、C项两端均不符合现行顺序。"}, {"id": 5, "chapter": "习近平强军思想", "stem": "有一种军事观强调：和平需要可靠实力保卫，越具备能战胜战能力，越能有效慑止战争。这集中体现了“五个坚持”中的哪一项？", "options": {"A": "坚持以武止戈", "B": "坚持积极进取", "C": "坚持敢打必胜", "D": "坚持统筹兼顾"}, "answer": "A", "explanation": "这一观点揭示了战争与和平、备战与慑战的辩证关系，属于“坚持以武止戈”的核心阐释；“积极进取”侧重争取主动，“敢打必胜”侧重战斗精神和胜战信念。"}, {"id": 6, "chapter": "习近平强军思想", "stem": "下列哪一项完整使用了现行强军战略布局的规范表述？", "options": {"A": "政治建军、改革强军、科技兴军、人才强军、依法治军", "B": "政治建军、改革强军、科技强军、人才强军、依法治军", "C": "政治建军、改革强军、科技强军、人才兴军、依法治军", "D": "政治建军、改革强军、科技强军、人才强军、从严治军"}, "answer": "B", "explanation": "现行五项强军战略布局的固定表述为政治建军、改革强军、科技强军、人才强军、依法治军。“科技兴军”和“从严治军”可在其他政策语境中使用，但不能替代本题所问固定表述中的“科技强军”和“依法治军”；C项则将“人才强军”改为“人才兴军”。"}, {"id": 7, "chapter": "习近平强军思想", "stem": "与2017年底概括的“十个明确”相比，2022年底拓展为“十一个明确”时新增的独立条目是？", "options": {"A": "明确军队是要准备打仗的", "B": "明确依法治军是我们党建军治军基本方式", "C": "明确作风优良是我军鲜明特色和政治优势", "D": "明确强军之道要在得人"}, "answer": "D", "explanation": "“军队是要准备打仗的”“依法治军”“作风优良”已在原“十个明确”中；拓展为“十一个明确”时，新增了“强军之道要在得人”这一重要内容。"}, {"id": 8, "chapter": "习近平强军思想", "stem": "下列哪一组完整列出了习近平强军思想蕴含的当代中国马克思主义军事观和方法论的“五个坚持”？", "options": {"A": "坚持政治引领、坚持以武止戈、坚持创新驱动、坚持统筹兼顾、坚持敢打必胜", "B": "坚持政治引领、坚持积极防御、坚持积极进取、坚持统筹兼顾、坚持敢打必胜", "C": "坚持政治引领、坚持以武止戈、坚持积极进取、坚持统筹兼顾、坚持敢打必胜", "D": "坚持政治建军、坚持以武止戈、坚持积极进取、坚持系统观念、坚持敢打必胜"}, "answer": "C", "explanation": "“五个坚持”依次为政治引领、以武止戈、积极进取、统筹兼顾、敢打必胜。创新驱动属于强军建设要求，积极防御属于军事战略思想，政治建军属于强军战略布局。"}, {"id": 9, "chapter": "习近平强军思想", "stem": "“十一个明确”关于推进强军事业提出了五个“更加注重”。下列哪一组与官方表述完全一致？", "options": {"A": "聚焦实战、创新驱动、体系建设、集约高效、军民融合", "B": "聚焦实战、创新驱动、联合制胜、集约高效、军民融合", "C": "聚焦实战、创新驱动、体系建设、质量效益、军民融合", "D": "聚焦实战、创新驱动、体系建设、集约高效、融合发展"}, "answer": "A", "explanation": "五项固定表述是聚焦实战、创新驱动、体系建设、集约高效、军民融合。其余选项分别用真实军事建设语汇“联合制胜”“质量效益”“融合发展”替换了其中一项，但都不符合该组固定表述。"}, {"id": 10, "chapter": "习近平强军思想", "stem": "新时代人民军队使命任务概括为“四个战略支撑”。下列各项中：①为巩固中国共产党领导和社会主义制度提供战略支撑；②为捍卫国家主权、统一、领土完整提供战略支撑；③为维护国家海外利益提供战略支撑；④为促进世界和平与发展提供战略支撑；⑤为维护国家海洋权益提供战略支撑；⑥为保障国家能源资源安全提供战略支撑。属于“四个战略支撑”固定表述的正确组合是？", "options": {"A": "①②⑤⑥", "B": "①③④⑤", "C": "②③④⑥", "D": "①②③④"}, "answer": "D", "explanation": "固定表述为①②③④。维护国家海洋权益和保障国家能源资源安全都属于重要安全任务，但并未在“四个战略支撑”的规范概括中单列。"}, {"id": 11, "chapter": "习近平强军思想", "stem": "深化国防和军队改革后，我军领导管理体系和作战指挥体系实现重塑。下列对应关系准确的是？", "options": {"A": "作战指挥体系为“中央军委—军种—部队”，领导管理体系为“中央军委—战区—部队”", "B": "作战指挥体系为“中央军委—战区—部队”，领导管理体系为“中央军委—军种—部队”", "C": "作战指挥体系为“中央军委—战区—军种—部队”，领导管理体系为“中央军委—军种—部队”", "D": "作战指挥体系为“中央军委—战区—部队”，领导管理体系为“中央军委—战区—军种—部队”"}, "answer": "B", "explanation": "改革贯彻“军委管总、战区主战、军种主建”总原则，形成“中央军委—战区—部队”的作战指挥体系和“中央军委—军种—部队”的领导管理体系。"}, {"id": 12, "chapter": "习近平强军思想", "stem": "某改革材料依次指出：①领导指挥体制运行不顺；②力量规模结构和编成不合理；③军人职业发展、待遇保障等政策不完善。按官方对改革所要破解问题的概括，三者依次对应？", "options": {"A": "体制性障碍、政策性问题、结构性矛盾", "B": "结构性矛盾、体制性障碍、政策性问题", "C": "体制性障碍、结构性矛盾、政策性问题", "D": "政策性问题、结构性矛盾、体制性障碍"}, "answer": "C", "explanation": "领导指挥体制问题对应“体制性障碍”，力量规模结构和编成问题对应“结构性矛盾”，职业发展和待遇保障政策问题对应“政策性问题”。本题要求理解三类概念的适用对象，而非只凭顺口程度记忆固定短语。"}, {"id": 13, "chapter": "习近平强军思想", "stem": "“强军之道要在得人”要求推动军事人员哪三个方面全面转型升级？", "options": {"A": "政治素质、队伍结构、培养使用", "B": "专业能力、力量布局、选拔管理", "C": "战斗素养、岗位配置、教育训练", "D": "能力素质、结构布局、开发管理"}, "answer": "D", "explanation": "规范表述是推动军事人员能力素质、结构布局、开发管理全面转型升级，锻造德才兼备的高素质、专业化新型军事人才。其余选项也使用宏观人才工作概念，但并非原文的三个维度。"}, {"id": 14, "chapter": "习近平强军思想", "stem": "党的二十大报告提出加快军队“四个现代化”。下列哪一项完整列出了报告中明确列举的这四项内容？", "options": {"A": "军事理论现代化、军队编制体制现代化、军事人员现代化、武器装备现代化", "B": "军事理论现代化、军队组织形态现代化、军事人员现代化、武器装备现代化", "C": "战争理论现代化、联合作战体系现代化、军人素质现代化、武器装备现代化", "D": "军事理论现代化、军队组织形态现代化、后勤保障现代化、武器装备现代化"}, "answer": "B", "explanation": "党的二十大报告列举的是军事理论、军队组织形态、军事人员、武器装备现代化。A、C、D均用相关但不等同的概念替换了其中一项或多项。2026年相关规划另对推进军事治理现代化作出部署，本题考查的是二十大报告明确列举的“四个现代化”。"}, {"id": 15, "chapter": "习近平强军思想", "stem": "新时代国防和军队改革被概括为环环相扣的“三大战役”。下列哪一组举措均主要属于第二场“脖子以下”改革？", "options": {"A": "军委机关由总部制调整为多部门制；成立五大战区", "B": "裁减军队员额30万；主要作战部队实行“军—旅—营”体制", "C": "成体系推进党的建设领域政策制度改革；成体系推进军事管理领域政策制度改革", "D": "裁减军队员额30万；建立“中央军委—战区—部队”的作战指挥体系"}, "answer": "B", "explanation": "A两项均属于第一场“脖子以上”改革，C两项均属于第三场军事政策制度改革，D分别混合了第二场和第一场改革；只有B两项均属于第二场规模结构和力量编成改革。"}, {"id": 16, "chapter": "习近平强军思想", "stem": "根据“十一个明确”关于建设创新型人民军队的原文，统筹推进的五个创新方面是哪一组？", "options": {"A": "军事理论、技术、组织、管理、文化", "B": "军事理论、科技、组织、管理、文化", "C": "军事理论、技术、体制、管理、文化", "D": "军事理论、技术、组织、治理、文化"}, "answer": "A", "explanation": "原文列举为军事理论、技术、组织、管理、文化等各方面创新。B、C、D分别以高度相关的“科技”“体制”“治理”替换了其中一个原文用语，因此不符合题干所限定的原文列举。"}, {"id": 17, "chapter": "习近平强军思想", "stem": "构建系统完备、严密高效的中国特色军事法治体系，需要形成下列哪四个体系？", "options": {"A": "军事法规制定体系、军事执法司法体系、军事监督问责体系、军人权益保障体系", "B": "军事法规制度体系、军事行政执法体系、军事审判检察体系、军事纪检监察体系", "C": "军事法规制度体系、军事法治实施体系、军事法治监督体系、军事法治保障体系", "D": "军事立法体系、军事执法体系、军事司法体系、军事守法体系"}, "answer": "C", "explanation": "官方概括为系统完备、严密高效的军事法规制度体系、军事法治实施体系、军事法治监督体系、军事法治保障体系。其余选项按一般法治环节或具体机构重新组合，不是规范表述。"}, {"id": 18, "chapter": "习近平强军思想", "stem": "《新时代的中国国防》白皮书阐释新时代军事战略方针时，强调了两个“相统一”。下列哪一项完全正确？", "options": {"A": "遏制战争与打赢战争相统一；战略上防御与战役战斗上进攻相统一", "B": "备战打仗与慑止危机相统一；战略上防御与战役战斗上反击相统一", "C": "遏制战争与打赢战争相统一；战略上进攻与战役战斗上防御相统一", "D": "防止战争与应对战争相统一；战略上防御与战役战斗上自卫相统一"}, "answer": "A", "explanation": "白皮书原文强调“遏制战争与打赢战争相统一”和“战略上防御与战役战斗上进攻相统一”。这一区分说明积极防御并不等于在战役战斗层面消极防守。"}, {"id": 19, "chapter": "习近平强军思想", "stem": "新时代人才强军战略锚定“四类人才”建设重点。下列“人才类别—建设要求”对应完全正确的是？", "options": {"A": "联合作战指挥人才—超前预置；新型作战力量人才—加速锻造；高层次科技创新人才—复合培养；高水平战略管理人才—激励扶持", "B": "联合作战指挥人才—复合培养；新型作战力量人才—激励扶持；高层次科技创新人才—加速锻造；高水平战略管理人才—超前预置", "C": "联合作战指挥人才—加速锻造；新型作战力量人才—超前预置；高层次科技创新人才—激励扶持；高水平战略管理人才—复合培养", "D": "联合作战指挥人才—激励扶持；新型作战力量人才—复合培养；高层次科技创新人才—超前预置；高水平战略管理人才—加速锻造"}, "answer": "C", "explanation": "四类人才及对应要求依次为：加速锻造联合作战指挥人才、超前预置新型作战力量人才、激励扶持高层次科技创新人才、复合培养高水平战略管理人才。"}, {"id": 20, "chapter": "习近平强军思想", "stem": "2023年3月8日，习近平在出席十四届全国人大一次会议解放军和武警部队代表团全体会议时，就巩固提高一体化国家战略体系和能力作出重要部署。下列“战略布局—战略资源—战略力量—目标”的组合完全正确的是？", "options": {"A": "战略布局一体整合—战略资源一体融合—战略力量一体运用—国防动员能力最大化", "B": "战略布局一体融合—战略资源一体运用—战略力量一体整合—军地资源效益最大化", "C": "战略布局一体运用—战略资源一体整合—战略力量一体融合—国家国防能力最大化", "D": "战略布局一体融合—战略资源一体整合—战略力量一体运用—国家战略能力最大化"}, "answer": "D", "explanation": "相关重要讲话要求加强各领域战略布局一体融合、战略资源一体整合、战略力量一体运用；关键是在“一体化”上下功夫，实现国家战略能力最大化。"}, {"id": 21, "chapter": "国防安全", "stem": "根据现行兵役法，我国兵役制度的完整表述是？", "options": {"A": "以义务兵役为主体，义务兵役与志愿兵役相结合", "B": "以志愿兵役为主体，志愿兵役与义务兵役相结合", "C": "以预备役为主体，预备役与现役相结合", "D": "志愿兵役、义务兵役和民兵役三者并列"}, "answer": "B", "explanation": "兵役法第三条规定，我国实行以志愿兵役为主体、志愿兵役与义务兵役相结合的兵役制度。"}, {"id": 22, "chapter": "国防安全", "stem": "2016年军区改革撤销原有多少个大军区，并成立多少个战区？", "options": {"A": "7个大军区、5个战区", "B": "7个大军区、6个战区", "C": "8个大军区、5个战区", "D": "8个大军区、6个战区"}, "answer": "A", "explanation": "2016年2月，原七大军区调整划设为东部、南部、西部、北部、中部五大战区。"}, {"id": 23, "chapter": "国防安全", "stem": "《中华人民共和国国防法》要求全面推进武装力量“四个现代化”。下列哪一项不属于法条明确列举的四项？", "options": {"A": "军事理论现代化", "B": "国防动员现代化", "C": "军队组织形态现代化", "D": "武器装备现代化"}, "answer": "B", "explanation": "国防法第二十四条列举的是军事理论、军队组织形态、军事人员和武器装备现代化，未将国防动员现代化列入这四项。"}, {"id": 24, "chapter": "国防安全", "stem": "《中华人民共和国国防法》对我国国防政策性质的表述是？", "options": {"A": "实行积极防御的国防政策", "B": "奉行独立自主的和平国防政策", "C": "奉行防御性国防政策", "D": "实行全民参与的国防政策"}, "answer": "C", "explanation": "国防法第六条明确，中华人民共和国奉行防御性国防政策；“积极防御”是军事战略方针层面的表述。"}, {"id": 25, "chapter": "国防安全", "stem": "根据国防法，下列哪一组完整构成中华人民共和国武装力量？", "options": {"A": "中国人民解放军、公安机关、民兵", "B": "中国人民解放军、中国人民武装警察部队、预备役人员", "C": "中国人民武装警察部队、国家综合性消防救援队伍、民兵", "D": "中国人民解放军、中国人民武装警察部队、民兵"}, "answer": "D", "explanation": "国防法规定，中华人民共和国武装力量由中国人民解放军、中国人民武装警察部队和民兵组成。"}, {"id": 26, "chapter": "国防安全", "stem": "以两栖作战武器为基本装备，主要遂行登陆作战任务，并可参加海军基地、港口和岛屿防御作战的是哪一支海军兵种？", "options": {"A": "海军陆战队", "B": "海军岸防兵", "C": "海军水面舰艇部队", "D": "海军航空兵"}, "answer": "A", "explanation": "国防部资料将海军陆战队定义为以两栖作战武器为基本装备、主要遂行登陆作战任务的海军兵种。"}, {"id": 27, "chapter": "国防安全", "stem": "中华人民共和国主席依照全国人大及其常委会的决定，可以履行哪项国防职权？", "options": {"A": "决定战争和和平的问题", "B": "决定全国总动员或者局部动员", "C": "宣布战争状态、发布动员令", "D": "统一指挥全国武装力量"}, "answer": "C", "explanation": "国家主席依照全国人大及其常委会的决定宣布战争状态、发布动员令；其他选项分别属于全国人大、全国人大常委会或中央军委的职权。"}, {"id": 28, "chapter": "国防安全", "stem": "总体国家安全观中，“宗旨—根本—基础”的对应关系是？", "options": {"A": "人民安全—基础，政治安全—宗旨，经济安全—保障", "B": "人民安全—宗旨，政治安全—根本，经济安全—基础", "C": "人民安全—宗旨，军事安全—根本，政治安全—基础", "D": "人民安全—保障，经济安全—根本，政治安全—宗旨"}, "answer": "B", "explanation": "国家安全法第三条明确，总体国家安全观以人民安全为宗旨、政治安全为根本、经济安全为基础。"}, {"id": 29, "chapter": "国防安全", "stem": "《军政》、《军志》军事文献是出现在我国古代的哪个时期【 】", "options": {"A": "西周时期", "B": "战国时期", "C": "秦代时期", "D": "三国时期"}, "answer": "A", "explanation": "军政是中国古代军事思想初步形成阶段的主要军事著作。与之同等的还有《军志》。是西周时期萌芽形态的兵书。"}, {"id": 30, "chapter": "国防安全", "stem": "根据2024年修订的国防教育法，国防教育的核心和目的分别是？", "options": {"A": "以爱国主义为核心，以履行国防义务为目的", "B": "以总体国家安全观为核心，以增强国防观念为目的", "C": "以爱国主义为核心，以普及国防知识为目的", "D": "以革命传统为核心，以掌握军事技能为目的"}, "answer": "A", "explanation": "国防教育法第二条规定，国家开展以爱国主义为核心、以履行国防义务为目的的国防教育。"}, {"id": 31, "chapter": "国防安全", "stem": "深化国防和军队改革形成的领导指挥体制格局是？", "options": {"A": "军委主战、战区主建、军种管总", "B": "军委管总、战区主战、军种主建", "C": "军委管总、战区主建、军种主战", "D": "军委主建、战区管总、军种主战"}, "answer": "B", "explanation": "深化改革形成军委管总、战区主战、军种主建的格局。"}, {"id": 32, "chapter": "国防安全", "stem": "《中华人民共和国国防法》第二条列举了国家军事活动以及与军事有关的若干方面活动。下列哪一项未被该条明确列举？", "options": {"A": "与军事有关的外交活动", "B": "与军事有关的科技活动", "C": "与军事有关的教育活动", "D": "与军事有关的文化活动"}, "answer": "D", "explanation": "国防法第二条明确列举与军事有关的政治、经济、外交、科技、教育等方面活动，未明确列举“文化活动”。题干限定为“未被明确列举”，不等同于断言文化活动绝对不适用该法。"}, {"id": 33, "chapter": "国防安全", "stem": "《战争论》一书的作者是【 】？", "options": {"A": "克劳塞维茨", "B": "亚当·斯密", "C": "茨威格", "D": "艾森豪威尔"}, "answer": "A", "explanation": "《战争论》是普鲁士军事理论家卡尔·冯·克劳塞维茨创作的一部军事理论著作，首次出版于1832年。《战争论》被誉为西方近代军事理论的经典之作，是军事思想史上自觉运用辩证法总结战争经验的战争理论经典，为近代西方军事思想体系的形成和发展奠定了理论基础，被誉为“战略学的《圣经》”。克劳塞维茨因此被视为西方近代军事理论的鼻祖。"}, {"id": 34, "chapter": "国防安全", "stem": "下列哪项完整准确地表述了《中华人民共和国国家安全法》所称“国家安全”？", "options": {"A": "国家政权、主权、统一和领土完整、人民福祉、经济社会可持续发展和国家其他重大利益绝对处于没有任何危险的状态，以及消除全部潜在风险的能力", "B": "国家主权、统一和领土完整、人民福祉及经济社会可持续发展没有现实危险，以及国家应对突发公共安全事件的能力", "C": "国家政权、主权、统一和领土完整、人民福祉、经济社会可持续发展和国家其他重大利益相对处于没有危险和不受内外威胁的状态，以及保障持续安全状态的能力", "D": "国家政权和社会主义制度不受外部干涉，国家主权、统一和领土完整不受军事侵犯，以及维护社会秩序稳定的能力"}, "answer": "C", "explanation": "国家安全法第二条从国家重大利益相对处于安全的状态和保障持续安全状态的能力两个层面作出完整定义。"}, {"id": 35, "chapter": "国防安全", "stem": "因执行国防勤务伤亡的，由当地县级人民政府依照《军人抚恤优待条例》等有关规定给予【 】。", "options": {"A": "救济补助", "B": "生活补贴", "C": "工伤保险", "D": "抚恤优待"}, "answer": "D", "explanation": "根据相关规定，因执行国防勤务伤亡的人员，其抚恤优待需参照军人相关标准，《军人抚恤优待条例》核心针对此类情形明确 “抚恤优待” 政策，而非单纯的救济补助、生活补贴或工伤保险。"}, {"id": 36, "chapter": "国防安全", "stem": "世界上最早提出信息战的人是【 】？", "options": {"A": "拿破仑", "B": "毛泽东", "C": "克劳塞维茨", "D": "沈伟光"}, "answer": "D", "explanation": "信息战这个概念最早出现在20世纪八十年代中期，是一位参加过作战的中国军人沈伟光首先发现并提出的，浙江大学1990年出版了世界首部中国人沈伟光著的《信息战》论。"}, {"id": 37, "chapter": "国防安全", "stem": "国家安全法规定，国家安全工作应当坚持哪一主体的领导？", "options": {"A": "全国人民代表大会常务委员会", "B": "国务院", "C": "中央军事委员会", "D": "中国共产党"}, "answer": "D", "explanation": "国家安全法明确，坚持中国共产党对国家安全工作的领导。"}, {"id": 38, "chapter": "国防安全", "stem": "台湾海峡是连接东海和【 】的重要水道，长约380公里。", "options": {"A": "渤海", "B": "黄海", "C": "北海", "D": "南海"}, "answer": "D", "explanation": ""}, {"id": 39, "chapter": "国防安全", "stem": "新时代国防的根本目标是【 】。", "options": {"A": "维护社会秩序安定", "B": "维护国家统一", "C": "坚决捍卫国家主权、安全、发展利益", "D": "保障国家安全"}, "answer": "C", "explanation": "摘自《新时代的中国国防》白皮书，中华人民共和国 国务院新闻办公室2019年7月，第二节《新时代中国防御性国防政策》"}, {"id": 40, "chapter": "国防安全", "stem": "为强化我国南海主权，2012年，经国务院批准在我国海南省设立【 】。", "options": {"A": "东方市", "B": "万宁市", "C": "三沙市", "D": "文昌市"}, "answer": "C", "explanation": ""}, {"id": 41, "chapter": "国防安全", "stem": "根据《中华人民共和国国防法》，国防经费的增长应当同时与哪两项相适应？", "options": {"A": "国防需求和国民经济发展水平", "B": "军队员额规模和国家财政收入增速", "C": "周边安全形势和居民消费价格水平", "D": "武器装备更新周期和地方经济发展水平"}, "answer": "A", "explanation": "国防法规定，国防经费的增长应当与国防需求和国民经济发展水平相适应。"}, {"id": 42, "chapter": "国防安全", "stem": "步兵是陆军中徒步或乘坐步兵战车、装甲输送车作战的兵种。我国古代军事史上的战斗主力曾经为战车兵，而从【 】开始，军队编制逐渐“毁车以为行”，步兵成为独立的兵种。", "options": {"A": "春秋战国时期", "B": "秦汉时期", "C": "三国两晋", "D": "南北朝时期"}, "answer": "A", "explanation": ""}, {"id": 43, "chapter": "国防安全", "stem": "《鬼谷子》指出：“制人者，握权也；见制于人者，制命也”，这体现的是哪种战略战术？【 】", "options": {"A": "力争主动", "B": "后发制人", "C": "集中兵力", "D": "出其不意"}, "answer": "A", "explanation": ""}, {"id": 44, "chapter": "国防安全", "stem": "士兵服现役的时间从何时起算？", "options": {"A": "本人领取入伍通知书之日", "B": "到达部队驻地之日", "C": "完成新兵训练之日", "D": "征集工作机构批准入伍之日"}, "answer": "D", "explanation": "兵役法明确，士兵服现役时间自征集工作机构批准入伍之日起算。"}, {"id": 45, "chapter": "国防安全", "stem": "毛泽东所说的“打得赢就打，打不赢就走”是【 】的通识解释。", "options": {"A": "游击战", "B": "运动战", "C": "阵地战", "D": "歼灭战"}, "answer": "A", "explanation": ""}, {"id": 46, "chapter": "国防安全", "stem": "下列关于战争谋略和战法理论中，不是出自孙子兵法的是【 】", "options": {"A": "“兵者，诡道也”", "B": "“严刑明赏，非所恃也。”", "C": "“知彼知已，百战不殆”", "D": "“攻其无备，出其不意”"}, "answer": "B", "explanation": "严刑明赏，非所恃也。举有功而进飨之，无功而励之。——《吴子兵法·励士》"}, {"id": 47, "chapter": "国防安全", "stem": "履行全军党的建设、组织工作、政治教育和军事人力资源管理等职能的部门是？【 】", "options": {"A": "中央军委联合参谋部", "B": "中央军委政治工作部", "C": "中央军委后勤保障部", "D": "中央军委装备发展部"}, "answer": "B", "explanation": ""}, {"id": 48, "chapter": "国防安全", "stem": "下列哪组完整列出了国防教育法规定的三项方针？", "options": {"A": "全民参与、突出重点、分类实施", "B": "全民参与、长期坚持、讲求实效", "C": "经常教育、集中教育、讲求实效", "D": "普及教育、重点教育、长期坚持"}, "answer": "B", "explanation": "国防教育法第六条规定，国防教育贯彻全民参与、长期坚持、讲求实效的方针。"}, {"id": 49, "chapter": "国防安全", "stem": "中华人民共和国第一任国防部长是【 】 。", "options": {"A": "朱德", "B": "叶剑英", "C": "粟裕", "D": "彭德怀"}, "answer": "D", "explanation": ""}, {"id": 50, "chapter": "国防安全", "stem": "公民在偶然机会下知悉涉及军事秘密的事项，应当怎么做？【 】", "options": {"A": "可以在报纸、互联网等公共媒体发布", "B": "可以在小范围内传播", "C": "应当予以保守，不再扩大知悉范围，必要时向有关部门报告", "D": "只向身边的人透露"}, "answer": "C", "explanation": ""}, {"id": 51, "chapter": "国防安全", "stem": "下列哪组完整列出了国防教育法规定的三组“相结合”原则？", "options": {"A": "经常教育与临时教育、普及教育与专业教育、理论教育与实践教育相结合", "B": "学校教育与社会教育、线上教育与线下教育、平时教育与战时教育相结合", "C": "经常教育与集中教育、普及教育与重点教育、理论教育与行为教育相结合", "D": "历史教育与现实教育、知识教育与技能教育、宣传教育与军事训练相结合"}, "answer": "C", "explanation": "国防教育法第六条规定实行经常教育与集中教育、普及教育与重点教育、理论教育与行为教育相结合。"}, {"id": 52, "chapter": "国防安全", "stem": "《孙子兵法》指出：“兵之情主速”，这指的是哪种战略战术【 】？", "options": {"A": "力争主动", "B": "先发制人", "C": "暗渡陈仓", "D": "速战速决"}, "answer": "D", "explanation": ""}, {"id": 53, "chapter": "国防安全", "stem": "游击战争“十六字诀” 是【 】。", "options": {"A": "敌进我追、敌退我退、敌驻我扰、敌疲我打", "B": "敌进我退、敌驻我打、敌疲我扰、敌退我追", "C": "敌进我退、敌驻我扰、敌疲我打、敌退我追", "D": "敌来我退、敌驻我扰、敌疲我打、敌走我追"}, "answer": "C", "explanation": ""}, {"id": 54, "chapter": "国防安全", "stem": "《孙子兵法》指出：“我专而敌分，我专为一，敌分为十，是以十攻其一也”，这体现的是哪种战略战术？【 】", "options": {"A": "全胜战略", "B": "常备不懈", "C": "力争主动", "D": "集中兵力"}, "answer": "D", "explanation": ""}, {"id": 55, "chapter": "国防安全", "stem": "根据反间谍法，反间谍工作的主管机关是？", "options": {"A": "国家安全机关", "B": "公安机关", "C": "国家保密行政管理部门", "D": "国家互联网信息部门"}, "answer": "A", "explanation": "反间谍法第六条规定，国家安全机关是反间谍工作的主管机关，其他有关部门依职责分工配合。"}, {"id": 56, "chapter": "国防安全", "stem": "孙武认为：“举师十万，日费千金”。因此用兵打仗，以速胜为勉，久战为戒。其中心思想是【 】", "options": {"A": "审己量敌，料胜决策", "B": "兵贵胜，不贵久", "C": "以智谋胜敌", "D": "不打无把握之仗"}, "answer": "B", "explanation": ""}, {"id": 57, "chapter": "国防安全", "stem": "中国在南海有4组群岛，它们是西沙群岛、东沙群岛、【 】和南沙群岛。", "options": {"A": "中沙群岛", "B": "北沙群岛", "C": "香港群岛", "D": "海南群岛"}, "answer": "A", "explanation": ""}, {"id": 58, "chapter": "国防安全", "stem": "国家安全法建立的国家安全审查和监管制度，完整针对的是？", "options": {"A": "可能影响国家安全的外商投资活动", "B": "关键信息基础设施的建设和运营活动", "C": "涉及国家安全的技术进出口活动", "D": "影响或者可能影响国家安全的事项和活动"}, "answer": "D", "explanation": "国家安全法规定，对影响或者可能影响国家安全的事项和活动进行国家安全审查，有关具体领域只是其中一部分。"}, {"id": 59, "chapter": "国防安全", "stem": "第一岛链是指北起日本群岛、琉球群岛，中接【 】，南至菲律宾、大巽他群岛的链形岛屿带。", "options": {"A": "崇明岛", "B": "舟山群岛", "C": "海南岛", "D": "台湾岛"}, "answer": "D", "explanation": ""}, {"id": 60, "chapter": "国防安全", "stem": "下列哪项属于国家安全法规定的公民和组织维护国家安全的义务？", "options": {"A": "及时报告危害国家安全活动的线索", "B": "决定是否对有关事项开展国家安全审查", "C": "依法发布国家安全风险预警信息", "D": "对危害国家安全的嫌疑人采取技术侦查措施"}, "answer": "A", "explanation": "及时报告危害国家安全活动的线索，是公民和组织的法定义务；其余选项属于国家机关依法履职的事项。"}, {"id": 61, "chapter": "国防安全", "stem": "下列哪组均属于国防法明确规定的公民和组织国防义务？", "options": {"A": "管理国防资产、审批军事采购", "B": "组织国防动员、决定战争和和平", "C": "保护国防设施、保守国防秘密", "D": "制定军事法规、统一指挥武装力量"}, "answer": "C", "explanation": "国防法明确规定公民和组织应当保护国防设施、保守国防秘密；其余事项属于国家机关或军事机关职权。"}, {"id": 62, "chapter": "国防安全", "stem": "公民和组织因国防建设和军事活动在经济上受到直接损失的，依法可以获得何种处理？", "options": {"A": "依照国家赔偿法一律取得赔偿", "B": "按军人抚恤优待标准获得抚恤", "C": "按照国防贡献大小获得奖励", "D": "依照国家有关规定取得补偿"}, "answer": "D", "explanation": "国防法规定，公民和组织因国防建设和军事活动在经济上受到直接损失的，可以依照国家有关规定取得补偿。"}, {"id": 63, "chapter": "国防安全", "stem": "下列哪组国家机构与国防职权对应正确？", "options": {"A": "国务院领导和管理国防建设事业；中央军事委员会领导全国武装力量", "B": "国务院领导全国武装力量；中央军事委员会领导和管理国防建设事业", "C": "全国人大常委会领导和管理国防建设事业；国家主席领导全国武装力量", "D": "国家主席领导和管理国防建设事业；国务院统一指挥全国武装力量"}, "answer": "A", "explanation": "国防法规定，国务院领导和管理国防建设事业，中央军事委员会领导全国武装力量。"}, {"id": 64, "chapter": "国防安全", "stem": "下列哪种网络活动被反间谍法明确纳入“间谍行为”的范围？", "options": {"A": "国内企业因管理疏忽造成内部业务数据泄露", "B": "间谍组织及其代理人等针对国家机关、涉密单位或者关键信息基础设施实施网络攻击、侵入、干扰、控制、破坏", "C": "个人利用漏洞干扰普通商业网站正常运行", "D": "境外企业通过公开渠道收集市场统计信息"}, "answer": "B", "explanation": "2023年修订的反间谍法将符合特定主体和对象条件的网络攻击、侵入、干扰、控制、破坏活动明确列为间谍行为。"}, {"id": 65, "chapter": "国防安全", "stem": "根据反间谍法，谁承担本单位反间谍安全防范工作的主体责任？", "options": {"A": "所在地国家安全机关", "B": "县级以上人民政府", "C": "机关、团体、企业事业组织和其他社会组织", "D": "本单位全体工作人员个人"}, "answer": "C", "explanation": "反间谍法规定，机关、团体、企业事业组织和其他社会组织承担本单位反间谍安全防范工作的主体责任。"}, {"id": 66, "chapter": "国防安全", "stem": "2024年修订的国防教育法确立的国防教育领导体制是？", "options": {"A": "集中统一、分级管理、军政协同", "B": "党委领导、政府负责、社会参与", "C": "军队主导、地方配合、分类实施", "D": "集中统一、分工负责、军地协同"}, "answer": "D", "explanation": "国防教育法第四条规定，建立集中统一、分工负责、军地协同的国防教育领导体制。"}, {"id": 67, "chapter": "国防安全", "stem": "有关机关依法采取处置国家安全危机的管控措施时，下列哪项同时准确概括了措施强度的“相适应”标准和多种措施之间的选择标准？", "options": {"A": "与危机已经造成的直接经济损失相适应；选择执行速度最快的措施", "B": "与社会关注程度和舆情影响范围相适应；选择威慑作用最强的措施", "C": "与危机可能造成危害的性质、程度和范围相适应；选择有利于最大程度保护公民、组织权益的措施", "D": "与履职机关现有人员和装备条件相适应；选择行政成本最低的措施"}, "answer": "C", "explanation": "国家安全法第六十六条要求管控措施与危机可能造成危害的性质、程度和范围相适应；有多种措施可选时，应选择有利于最大程度保护公民、组织权益的措施。"}, {"id": 68, "chapter": "国防安全", "stem": "国家安全机关工作人员依法查验有关个人或者组织的电子设备、设施及有关程序、工具时，法定最低审批层级和证件要求是？", "options": {"A": "经县级以上国家安全机关负责人批准，并出示人民警察证", "B": "经省级国家安全机关负责人批准，并出示检查决定书", "C": "经同级人民政府负责人批准，并出示工作证件和搜查证", "D": "经设区的市级以上国家安全机关负责人批准，并出示工作证件"}, "answer": "D", "explanation": "反间谍法规定，执行反间谍工作任务的国家安全机关工作人员，经设区的市级以上国家安全机关负责人批准并出示工作证件，可以依法实施相关查验。"}, {"id": 69, "chapter": "国防安全", "stem": "对陆地军事禁区和陆地军事管理区内相关建设、地下空间利用的禁止性规定作出例外批准，其法定最低层级分别是？", "options": {"A": "战区级以上军事机关、军级以上军事机关", "B": "军级以上军事机关、军级以上军事机关", "C": "战区级以上军事机关、战区级以上军事机关", "D": "中央军事委员会、战区级以上军事机关"}, "answer": "A", "explanation": "军事设施保护法对两类区域区分审批层级：陆地军事禁区的相关例外须经战区级以上军事机关批准，陆地军事管理区的相关例外须经军级以上军事机关批准。"}, {"id": 70, "chapter": "国防安全", "stem": "国家决定进入紧急状态、战争状态或者实施国防动员后，有关机关采取限制公民和组织权利、增加公民和组织义务的特别措施，其权力依据应当是？", "options": {"A": "法律规定或者国务院行政法规规定", "B": "法律规定或者全国人民代表大会常务委员会规定", "C": "中央国家安全领导机构决定或者国务院命令", "D": "全国人民代表大会决定或者中央军事委员会命令"}, "answer": "B", "explanation": "国家安全法第六十五条规定，在相应状态下，履行国家安全危机管控职责的有关机关依照法律规定或者全国人大常委会规定，有权采取相关特别措施。"}, {"id": 71, "chapter": "军事科技", "stem": "运-20基本型飞机的主要用途是？", "options": {"A": "战略空运", "B": "空中加油保障", "C": "空中预警指挥", "D": "远程海上巡逻"}, "answer": "A", "explanation": "运-20基本型是我国自主研制的大型战略运输机，主要承担战略空运任务。"}, {"id": 72, "chapter": "军事科技", "stem": "下列哪一组全部是我国四大航天发射场？", "options": {"A": "酒泉、太原、西昌、文昌", "B": "酒泉、太原、文昌、海阳", "C": "酒泉、西昌、文昌、烟台", "D": "太原、西昌、文昌、海南"}, "answer": "A", "explanation": "国家航天局介绍的我国四大航天发射场为酒泉、太原、西昌和文昌。"}, {"id": 73, "chapter": "军事科技", "stem": "航空母舰最核心的作战功能是？", "options": {"A": "担任编队区域防空指挥舰", "B": "搭载并运用舰载航空兵", "C": "遂行两栖兵力投送", "D": "实施远程对陆导弹打击"}, "answer": "B", "explanation": "航空母舰以舰载机为主要作战力量，是海上机动航空作战平台。"}, {"id": 74, "chapter": "军事科技", "stem": "我国目前已经建成了四个卫星发射中心，下列哪个不是【 】？", "options": {"A": "太原", "B": "西安", "C": "酒泉", "D": "文昌"}, "answer": "B", "explanation": "中国卫星发射中心总共为以下4个:酒泉卫星发射中心、西昌卫星发射中心、太原卫星发射中心，以及文昌卫星发射中心。"}, {"id": 75, "chapter": "军事科技", "stem": "我国制造的一款手枪在国外被赋予“黑星”的美名，请问是哪一款？【 】", "options": {"A": "69式手枪", "B": "64式手枪", "C": "54式手枪", "D": "77式手枪"}, "answer": "C", "explanation": ""}, {"id": 76, "chapter": "军事科技", "stem": "下列哪型飞机属于隐身舰载战斗机？", "options": {"A": "歼-35", "B": "歼-15T", "C": "歼-20", "D": "苏-33"}, "answer": "A", "explanation": "歼-35是福建舰舰载机体系中的隐身舰载战斗机。"}, {"id": 77, "chapter": "军事科技", "stem": "下列哪一种是舰艇装备最广泛的主力战舰【 】。", "options": {"A": "驱逐舰", "B": "护卫舰", "C": "巡洋舰", "D": "战列舰"}, "answer": "B", "explanation": ""}, {"id": 78, "chapter": "军事科技", "stem": "下列哪型飞机主要承担舰载固定翼预警任务？", "options": {"A": "空警-500", "B": "空警-600", "C": "直-18J", "D": "空警-2000"}, "answer": "B", "explanation": "空警-600是固定翼舰载预警机。"}, {"id": 79, "chapter": "军事科技", "stem": "人民防空提出的“三防”是指【 】。", "options": {"A": "防空袭、防破坏、防危害", "B": "防轻武器、防重武器、防导弹", "C": "防核武器、防化学武器、防生物武器", "D": "防核武器、防生化武器、防导弹"}, "answer": "C", "explanation": ""}, {"id": 80, "chapter": "军事科技", "stem": "北斗三号全球系统的基本空间星座由多少颗卫星构成？", "options": {"A": "27颗", "B": "35颗", "C": "30颗", "D": "55颗"}, "answer": "C", "explanation": "北斗三号基本星座由24颗中圆地球轨道卫星、3颗倾斜地球同步轨道卫星和3颗地球静止轨道卫星构成。"}, {"id": 81, "chapter": "军事科技", "stem": "【 】战争是信息化战争进入成熟期的开始。", "options": {"A": "伊拉克", "B": "阿富汗", "C": "科索沃", "D": "海湾"}, "answer": "C", "explanation": "科索沃战争是一场由科索沃的民族矛盾直接引发、以美国为首的北公约组织的推动下、发生在20世纪末的一场重要的高技术局部战争。科索沃战争是一场背景深刻、影响广泛的现代局部战争，对世纪之交的世界政治格局和军事理论的发展均产生了重要的影响。战争结束后，俄罗斯彻底被挤出了在东欧的原有势力圈。"}, {"id": 82, "chapter": "军事科技", "stem": "冷兵器按作战使用可分为步战兵器、车战兵器、【 】、水战兵器和攻守城器械等。", "options": {"A": "抛射兵器", "B": "马战兵器", "C": "骑战兵器", "D": "炮战兵器"}, "answer": "C", "explanation": "冷兵器按作战使用场景分类，需对应不同作战方式，步战、车战、骑战、水战是古代典型作战类型，“骑战兵器” 契合该分类逻辑；A 是按兵器作用方式分类，B 表述非标准分类术语，D “炮战”多与热兵器关联。"}, {"id": 83, "chapter": "军事科技", "stem": "北斗系统建设的“三步走”顺序是？", "options": {"A": "先服务亚太，再服务中国，最后服务全球", "B": "先服务中国，再服务亚太，最后服务全球", "C": "先服务中国，再服务'一带一路'沿线，最后服务全球", "D": "先服务中国，再服务全球，最后服务亚太"}, "answer": "B", "explanation": "北斗一号、北斗二号、北斗三号分别对应中国、亚太和全球服务。"}, {"id": 84, "chapter": "军事科技", "stem": "在信息化战场中夺取战场主动权的关键是【 】。", "options": {"A": "制空权", "B": "制陆权", "C": "制信息权", "D": "制海权"}, "answer": "C", "explanation": ""}, {"id": 85, "chapter": "军事科技", "stem": "现代战争手段的核心是【 】", "options": {"A": "兵力", "B": "武器装备", "C": "信息能力", "D": "作战空间"}, "answer": "C", "explanation": ""}, {"id": 86, "chapter": "军事科技", "stem": "在没有地面移动通信网络覆盖时，能够让用户通过卫星发送简短信息的北斗特色服务是？", "options": {"A": "星基增强", "B": "国际搜救", "C": "短报文通信", "D": "精密单点定位"}, "answer": "C", "explanation": "北斗短报文通信可在缺少地面通信网络覆盖时，通过卫星实现简短信息传递。"}, {"id": 87, "chapter": "军事科技", "stem": "1991年海湾战争期间，哪种防空导弹成功拦截了伊拉克的“飞毛腿”导弹？【 】", "options": {"A": "“毒刺”", "B": "“海麻雀”", "C": "“响尾蛇”", "D": "“爱国者”"}, "answer": "D", "explanation": ""}, {"id": 88, "chapter": "军事科技", "stem": "GPS卫星导航定位至少需要【 】卫星才能精确定位？", "options": {"A": "两颗", "B": "三颗", "C": "四颗", "D": "五颗"}, "answer": "C", "explanation": "卫星导航定位系统需要至少4颗卫星来确定用户的三维位置信息，即经度、维度和海拔高度"}, {"id": 89, "chapter": "军事科技", "stem": "1984年的国庆大阅兵上，武器装备全部是国产现代化武器，【 】部队首次亮相。", "options": {"A": "特种兵部队", "B": "电子对抗部队", "C": "战略导弹部队", "D": "空军部队"}, "answer": "C", "explanation": ""}, {"id": 90, "chapter": "军事科技", "stem": "卫星导航系统中的“授时”是指？", "options": {"A": "提供卫星轨道参数和状态信息", "B": "提供用户三维位置与速度信息", "C": "监测导航信号的完整性", "D": "提供高精度时间基准"}, "answer": "D", "explanation": "授时服务向用户提供统一、精确的时间信息。"}, {"id": 91, "chapter": "军事科技", "stem": "炮的口径通常大于【 】毫米。", "options": {"A": "20", "B": "30", "C": "35", "D": "40"}, "answer": "A", "explanation": ""}, {"id": 92, "chapter": "军事科技", "stem": "以舰载机为主要武器并作为其海上活动基地的大型水面战斗舰艇是【 】。", "options": {"A": "驱逐舰", "B": "巡洋舰", "C": "战列舰", "D": "航空母舰"}, "answer": "D", "explanation": ""}, {"id": 93, "chapter": "军事科技", "stem": "定向能武器与传统动能武器的主要区别是？", "options": {"A": "以爆炸冲击波和破片作用目标", "B": "以高速实体弹丸的动能作用目标", "C": "以定向能量束作用目标", "D": "以网络指令侵入目标信息系统"}, "answer": "C", "explanation": "定向能武器以激光、微波等定向能量作用于目标。"}, {"id": 94, "chapter": "军事科技", "stem": "未来信息化战争具有完全不同于以往战争形态的鲜明特征，请从下列各项中选出不正确的一项。【 】", "options": {"A": "作战空间超大多维化，从传统意义上的陆、海、空“三维空间”拓展为“七维空间”的综合较量", "B": "作战时间有延缓趋势，战争节奏变慢、时间拖长", "C": "武器装备信息化，主要包括信息武器、单兵数字化装备和C4ISR 系统", "D": "战争行动精确化，实现了精确打击、精确侦察、精确定位、精确保障"}, "answer": "B", "explanation": ""}, {"id": 95, "chapter": "军事科技", "stem": "信息化战争在打击目标的控制上，主要打击的目标不包含【 】", "options": {"A": "指挥控制中枢", "B": "重要军事设施", "C": "重兵集团", "D": "所有前线部队"}, "answer": "D", "explanation": ""}, {"id": 96, "chapter": "军事科技", "stem": "强降雨、浓雾等天气可能降低激光武器效能，主要原因是？", "options": {"A": "大气会对光束产生吸收和散射", "B": "雨雾主要改变目标的红外辐射特征", "C": "大气湍流主要影响平台姿态而非光束传播", "D": "雨雾会使目标距离估计产生系统性偏差"}, "answer": "A", "explanation": "大气吸收、散射和湍流会影响激光束传播。"}, {"id": 97, "chapter": "军事科技", "stem": "被称为动能武器的眼睛的是【 】", "options": {"A": "超高速发射装置", "B": "探测系统", "C": "制导系统", "D": "导弹"}, "answer": "B", "explanation": ""}, {"id": 98, "chapter": "军事科技", "stem": "在信息化战争中，战争的观念逐渐改变，【 】观念逐步确立。", "options": {"A": "消耗战", "B": "歼灭战", "C": "运动战", "D": "瘫痪战"}, "answer": "D", "explanation": ""}, {"id": 99, "chapter": "军事科技", "stem": "嫦娥四号任务实现了人类探测器首次在哪里软着陆？", "options": {"A": "月球正面", "B": "月球背面", "C": "火星乌托邦平原", "D": "月球南极地区"}, "answer": "B", "explanation": "嫦娥四号实现了人类探测器首次月球背面软着陆和巡视探测。"}, {"id": 100, "chapter": "军事科技", "stem": "人类战争史上首次大规模使用化学武器是在什么时期？【 】", "options": {"A": "第二次世界大战", "B": "第一次世界大战", "C": "冷战", "D": "也门战争"}, "answer": "B", "explanation": ""}, {"id": 101, "chapter": "军事科技", "stem": "精确制导武器的直接命中概率是【 】以上。", "options": {"A": "40%", "B": "50%", "C": "60%", "D": "70%"}, "answer": "B", "explanation": "精确是相对的概念，是指这些武器对射程内的点目标如坦克、装甲车、飞机、舰艇、雷达、桥梁、指挥中心等有很高的直接命中率。多数人认为，直接命中概率高于50%的制导武器才称为精确制导武器。"}, {"id": 102, "chapter": "军事科技", "stem": "我军开发研制的第一款战术情景对抗游戏的名称是【 】。", "options": {"A": "红色警戒", "B": "光荣使命", "C": "战地", "D": "使命召唤"}, "answer": "B", "explanation": ""}, {"id": 103, "chapter": "军事科技", "stem": "嫦娥五号任务的重要成果是？", "options": {"A": "实现我国首次月球背面软着陆巡视", "B": "实现我国首次火星着陆巡视探测", "C": "实现我国首次地外天体采样返回", "D": "实现我国首次载人飞船与空间站对接"}, "answer": "C", "explanation": "嫦娥五号完成月球采样并携带样品返回地球。"}, {"id": 104, "chapter": "军事科技", "stem": "采用精确打击特种作战相结合的作战思想的典型战争是【 】", "options": {"A": "海湾战争", "B": "科索沃战争", "C": "阿富汗战争", "D": "伊拉克战争"}, "answer": "C", "explanation": ""}, {"id": 105, "chapter": "军事科技", "stem": "运载火箭技术同什么军事技术有关？【 】", "options": {"A": "洲际弹道导弹", "B": "巡航导弹", "C": "原子弹", "D": "无人驾驶侦察机"}, "answer": "A", "explanation": "一般来说，洲际弹道导弹的射程至少应达到5500-8000公里。洲际弹道导弹一般（但并非一定）装备1枚核或热核弹头，其典型构成为：液体或固体推进装置，二级或多级助推火箭，惯性制导系统（并可加装星座导航、卫星导航或末端制导系统），一个或多个载入飞行器，每个载入飞行器各含有一枚弹头。"}, {"id": 106, "chapter": "军事科技", "stem": "天问一号是我国首次开展的哪类行星探测任务？", "options": {"A": "月球采样返回", "B": "小行星采样返回", "C": "木星系探测", "D": "火星探测"}, "answer": "D", "explanation": "天问一号一次实现火星环绕、着陆和巡视探测。"}, {"id": 107, "chapter": "军事科技", "stem": "军事测绘的主要任务包括:生产测绘成果和【 】", "options": {"A": "获取地形资料", "B": "实施测绘保障", "C": "掌握战场地形情况", "D": "保障技术兵器准确定位"}, "answer": "B", "explanation": ""}, {"id": 108, "chapter": "军事科技", "stem": "坦克按战斗分为轻型、中型和重型三种，重型坦克战斗全重为【 】", "options": {"A": "20-30吨", "B": "30一40 吨", "C": "40 吨以上", "D": "50 吨以上"}, "answer": "C", "explanation": "20世纪60年代以前，坦克多按战斗全重和火炮口径以及用途分为轻、中、重型。通常重型坦克重42～80吨，火炮口径最大为152毫米，主要用于支援中型坦克战斗。"}, {"id": 109, "chapter": "军事科技", "stem": "预警机的核心任务通常是？", "options": {"A": "远程电子干扰与压制", "B": "空中预警探测与指挥引导", "C": "空中加油与航程延伸", "D": "对地精确打击与战果评估"}, "answer": "B", "explanation": "固定翼预警机依托雷达和指挥系统扩大空情感知与指挥范围。"}, {"id": 110, "chapter": "军事科技", "stem": "导弹发射要达到一定的速度。第一宇宙速度也称环绕速度，具体为【 】。", "options": {"A": "7.6 千米/秒", "B": "7.9 千米/秒", "C": "11.2 千米/秒", "D": "16.7 千米/秒"}, "answer": "B", "explanation": ""}, {"id": 111, "chapter": "军事科技", "stem": "相较滑跃起飞，弹射起飞的一项主要优势是？", "options": {"A": "缩短舰载机着舰滑跑距离", "B": "降低舰载机雷达反射截面积", "C": "提高舰载机着舰阶段的下滑稳定性", "D": "可提高舰载机起飞重量和出动效率"}, "answer": "D", "explanation": "弹射系统有利于舰载机以更大载荷起飞，并提升多机种运用能力。"}, {"id": 112, "chapter": "军事科技", "stem": "文昌航天发射场纬度较低，这一地理条件有利于？", "options": {"A": "缩短火箭穿越稠密大气层的距离", "B": "利用较大的地球自转线速度提高运载效率", "C": "扩大任务可选发射方位角的范围", "D": "延长发射场对入轨卫星的测控弧段"}, "answer": "B", "explanation": "低纬度发射可更多利用地球自转速度，适合发射大型、高轨航天器。"}, {"id": 113, "chapter": "军事科技", "stem": "太原卫星发射中心较适合发射哪类卫星？", "options": {"A": "地球同步转移轨道卫星", "B": "低倾角近地轨道载荷", "C": "太阳同步轨道卫星", "D": "月球转移轨道探测器"}, "answer": "C", "explanation": "太原发射中心具有发射太阳同步轨道和极轨卫星的突出能力。"}, {"id": 114, "chapter": "军事科技", "stem": "西昌卫星发射中心长期承担较多哪类发射任务？", "options": {"A": "太阳同步轨道遥感卫星", "B": "近地轨道空间站舱段", "C": "返回式科学试验卫星", "D": "地球同步轨道通信卫星"}, "answer": "D", "explanation": "西昌发射中心适合执行地球同步转移轨道等高轨发射任务。"}, {"id": 115, "chapter": "军事科技", "stem": "福建舰电磁弹射系统能够支持多型舰载机起飞，体现的是哪项体系优势？", "options": {"A": "对不同重量和用途飞机的适配能力", "B": "通过统一弹射参数降低舰面保障复杂度", "C": "同步改善不同机型着舰时的阻拦性能", "D": "使不同机型采用相同起飞重量和离舰速度"}, "answer": "A", "explanation": "电磁弹射可精确调节弹射能量，利于适配战斗机、预警机等不同机型。"}, {"id": 116, "chapter": "军事科技", "stem": "北斗三号采用三类轨道混合星座，主要目的之一是？", "options": {"A": "在不增加星数的情况下提高所有卫星可见仰角", "B": "兼顾全球覆盖与区域增强", "C": "利用统一地面轨迹简化全球运行控制", "D": "由高轨卫星集中承担星间链路转发"}, "answer": "B", "explanation": "MEO、IGSO和GEO混合构型兼顾全球服务与亚太区域增强。"}, {"id": 117, "chapter": "军事科技", "stem": "高功率微波武器更适合主要作用于目标的哪类系统？", "options": {"A": "光电成像与红外探测系统", "B": "装甲与承力结构", "C": "燃油、弹药等保障物资", "D": "电子与信息系统"}, "answer": "D", "explanation": "高功率微波可耦合进入电子设备，对电路和信息系统造成干扰或毁伤。"}, {"id": 118, "chapter": "军事科技", "stem": "舰载固定翼预警机通常需要弹射起飞，最关键的原因是？", "options": {"A": "预警雷达工作时会干扰舰上导航设备", "B": "机体较重且需携带雷达和任务设备", "C": "螺旋桨飞机无法采用滑跃甲板起飞", "D": "预警机必须以高于战斗机的离舰速度起飞"}, "answer": "B", "explanation": "固定翼预警机重量和任务载荷较大，弹射系统可保障其在有限甲板长度上安全起飞。"}, {"id": 119, "chapter": "军事科技", "stem": "与传统弹药相比，定向能武器可持续作战能力更直接受制于？", "options": {"A": "光束指向与目标跟踪精度", "B": "大气传输窗口与能见度条件", "C": "平台供能与热管理能力", "D": "目标材料对能量的吸收和反射特性"}, "answer": "C", "explanation": "定向能武器需要持续、稳定的高功率能源，并需及时散热。"}, {"id": 120, "chapter": "军事科技", "stem": "福建舰舰载机体系同时配置战斗机、电子战飞机和预警机，主要体现现代航母作战的什么特点？", "options": {"A": "以制空权争夺为中心的单一任务优化", "B": "以增加舰载机种类为目标的平台功能扩展", "C": "以舰载航空兵取代水面舰艇火力的任务重构", "D": "体系化空中作战与信息支援"}, "answer": "D", "explanation": "多机种协同可形成制空、预警、电子支援和指挥引导等体系能力。"}, {"id": 121, "chapter": "时事政治", "stem": "2026年是我国实施第几个五年规划的开局之年？", "options": {"A": "第十五个五年规划", "B": "第十三个五年规划", "C": "第十四个五年规划", "D": "第十六个五年规划"}, "answer": "A", "explanation": "“十五五”时期为2026年至2030年，2026年是开局之年。"}, {"id": 122, "chapter": "时事政治", "stem": "“十五五”规划对应的时间范围是？", "options": {"A": "2021—2025年", "B": "2026—2030年", "C": "2025—2029年", "D": "2031—2035年"}, "answer": "B", "explanation": "“十五五”规划纲要规划期为2026年至2030年。"}, {"id": 123, "chapter": "时事政治", "stem": "2026年召开的全国人民代表大会会议是？", "options": {"A": "十四届全国人大三次会议", "B": "十四届全国人大五次会议", "C": "十四届全国人大四次会议", "D": "十五届全国人大一次会议"}, "answer": "C", "explanation": "2026年召开的是第十四届全国人民代表大会第四次会议。"}, {"id": 124, "chapter": "时事政治", "stem": "2026年政府工作报告提出的国内生产总值增长预期目标是？", "options": {"A": "4%左右", "B": "5%左右", "C": "5%—5.5%", "D": "4.5%—5%"}, "answer": "D", "explanation": "2026年国内生产总值增长预期目标为4.5%—5%。"}, {"id": 125, "chapter": "时事政治", "stem": "台湾光复纪念日是每年的哪一天？", "options": {"A": "10月25日", "B": "9月3日", "C": "12月13日", "D": "7月7日"}, "answer": "A", "explanation": "我国将10月25日设立为台湾光复纪念日。"}, {"id": 126, "chapter": "时事政治", "stem": "党的二十届四中全会重点审议通过了关于制定哪一规划的建议？", "options": {"A": "'十四五'规划", "B": "2035年远景目标", "C": "“十五五”规划", "D": "'十六五'规划"}, "answer": "C", "explanation": "全会审议通过了《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》。"}, {"id": 127, "chapter": "时事政治", "stem": "2025年上海合作组织峰会在我国哪座城市举行？", "options": {"A": "上海", "B": "青岛", "C": "北京", "D": "天津"}, "answer": "D", "explanation": "2025年上海合作组织峰会在天津举行。"}, {"id": 128, "chapter": "时事政治", "stem": "2026年城镇调查失业率预期目标是？", "options": {"A": "5.5%左右", "B": "5%左右", "C": "5.2%左右", "D": "6%左右"}, "answer": "A", "explanation": "2026年城镇调查失业率预期目标为5.5%左右。"}, {"id": 129, "chapter": "时事政治", "stem": "2026年城镇新增就业预期目标是？", "options": {"A": "1100万人以上", "B": "1200万人以上", "C": "1300万人以上", "D": "1400万人以上"}, "answer": "B", "explanation": "政府工作报告提出城镇新增就业1200万人以上。"}, {"id": 130, "chapter": "时事政治", "stem": "2026年居民消费价格涨幅预期目标是？", "options": {"A": "1.5%左右", "B": "2.5%左右", "C": "2%左右", "D": "3%左右"}, "answer": "C", "explanation": "居民消费价格涨幅预期目标为2%左右。"}, {"id": 131, "chapter": "时事政治", "stem": "2026年粮食产量预期目标是？", "options": {"A": "1.35万亿斤左右", "B": "1.45万亿斤左右", "C": "1.5万亿斤左右", "D": "1.4万亿斤左右"}, "answer": "D", "explanation": "政府工作报告提出粮食产量1.4万亿斤左右。"}, {"id": 132, "chapter": "时事政治", "stem": "2026年单位国内生产总值二氧化碳排放预期降低约多少？", "options": {"A": "3.8%", "B": "3.5%", "C": "4%", "D": "4.5%"}, "answer": "A", "explanation": "2026年单位国内生产总值二氧化碳排放预期降低3.8%左右。"}, {"id": 133, "chapter": "时事政治", "stem": "和平和发展是当今世界的主题，它是谁提出的？【 】", "options": {"A": "毛泽东", "B": "邓小平", "C": "江泽民", "D": "胡锦涛"}, "answer": "B", "explanation": ""}, {"id": 134, "chapter": "时事政治", "stem": "2026年拟按多少左右安排赤字率？", "options": {"A": "3%", "B": "4%", "C": "3.5%", "D": "4.5%"}, "answer": "B", "explanation": "2026年赤字率按4%左右安排。"}, {"id": 135, "chapter": "时事政治", "stem": "2026年全国财政赤字规模为多少？", "options": {"A": "5.66万亿元", "B": "6.06万亿元", "C": "5.89万亿元", "D": "6.39万亿元"}, "answer": "C", "explanation": "预算报告提出全国财政赤字5.89万亿元。"}, {"id": 136, "chapter": "时事政治", "stem": "2026年拟发行超长期特别国债多少？", "options": {"A": "1万亿元", "B": "1.5万亿元", "C": "2万亿元", "D": "1.3万亿元"}, "answer": "D", "explanation": "2026年拟发行超长期特别国债1.3万亿元。"}, {"id": 137, "chapter": "时事政治", "stem": "2026年拟安排地方政府专项债券多少？", "options": {"A": "4.4万亿元", "B": "4万亿元", "C": "4.8万亿元", "D": "5万亿元"}, "answer": "A", "explanation": "2026年地方政府专项债券拟安排4.4万亿元。"}, {"id": 138, "chapter": "时事政治", "stem": "2026年中央预算内投资拟安排多少？", "options": {"A": "7350亿元", "B": "7550亿元", "C": "7750亿元", "D": "8000亿元"}, "answer": "B", "explanation": "中央预算内投资拟安排7550亿元。"}, {"id": 139, "chapter": "时事政治", "stem": "2026年拟安排支持消费品以旧换新的超长期特别国债资金是多少？", "options": {"A": "2000亿元", "B": "3000亿元", "C": "2500亿元", "D": "3500亿元"}, "answer": "C", "explanation": "预算报告提出安排2500亿元支持消费品以旧换新。"}, {"id": 140, "chapter": "时事政治", "stem": "第二届中国—中亚峰会在何地举行？", "options": {"A": "中国西安", "B": "乌兹别克斯坦撒马尔罕", "C": "塔吉克斯坦杜尚别", "D": "哈萨克斯坦阿斯塔纳"}, "answer": "D", "explanation": "第二届中国—中亚峰会于2025年在哈萨克斯坦首都阿斯塔纳举行。"}, {"id": 141, "chapter": "时事政治", "stem": "党的二十届四中全会于2025年何时举行？", "options": {"A": "10月20日至23日", "B": "2025年7月20日至23日", "C": "2025年9月20日至23日", "D": "2025年10月23日至26日"}, "answer": "A", "explanation": "党的二十届四中全会于2025年10月20日至23日在北京举行。"}, {"id": 142, "chapter": "时事政治", "stem": "第二届中国—中亚峰会举行的日期是？", "options": {"A": "2025年6月16日", "B": "2025年6月17日", "C": "2025年6月18日", "D": "2025年7月17日"}, "answer": "B", "explanation": "第二届中国—中亚峰会于2025年6月17日在阿斯塔纳举行。"}, {"id": 143, "chapter": "时事政治", "stem": "中国同中亚国家将哪一时段确定为“中国中亚合作高质量发展年”？", "options": {"A": "2024—2025年", "B": "2026—2027年", "C": "2025—2026年", "D": "2027—2028年"}, "answer": "C", "explanation": "峰会成果文件明确将2025—2026年确定为中国中亚合作高质量发展年。"}, {"id": 144, "chapter": "时事政治", "stem": "根据第二届中国—中亚峰会成果安排，下一届峰会拟于哪一年由中国主办？", "options": {"A": "2026年", "B": "2028年", "C": "2029年", "D": "2027年"}, "answer": "D", "explanation": "阿斯塔纳宣言明确，下一届峰会将于2027年由中国主办。"}, {"id": 145, "chapter": "时事政治", "stem": "党的十九届五中全会提出了到【 】年基本实现社会主义现代化远景目标。", "options": {"A": "2045", "B": "2035", "C": "2030", "D": "2050"}, "answer": "B", "explanation": ""}, {"id": 146, "chapter": "时事政治", "stem": "“十五五”规划纲要设置的主要指标共有多少项？", "options": {"A": "20项", "B": "18项", "C": "22项", "D": "25项"}, "answer": "A", "explanation": "“十五五”规划纲要设置20项主要指标。"}, {"id": 147, "chapter": "时事政治", "stem": "“十五五”规划纲要主要指标分为多少个方面？", "options": {"A": "4个方面", "B": "5个方面", "C": "6个方面", "D": "7个方面"}, "answer": "B", "explanation": "规划纲要将20项主要指标分列在5个方面。"}, {"id": 148, "chapter": "时事政治", "stem": "“十五五”规划期末，劳动年龄人口平均受教育年限目标是？", "options": {"A": "11.3年", "B": "11.5年", "C": "11.7年", "D": "12年"}, "answer": "C", "explanation": "规划纲要提出劳动年龄人口平均受教育年限达到11.7年。"}, {"id": 149, "chapter": "时事政治", "stem": "“十五五”规划期末，人均预期寿命目标是？", "options": {"A": "79岁", "B": "79.5岁", "C": "80.5岁", "D": "80岁"}, "answer": "D", "explanation": "规划纲要提出人均预期寿命达到80岁。"}, {"id": 150, "chapter": "时事政治", "stem": "实现“两个一百年”奋斗目标、实现中华民族伟大复兴的中国梦,不断提高人民生活水平,必须坚定不移把【 】作为党执政兴国的第一要务。", "options": {"A": "创新", "B": "改革", "C": "发展", "D": "开放"}, "answer": "C", "explanation": ""}, {"id": 151, "chapter": "时事政治", "stem": "“十五五”规划期末，养老机构护理型床位占比目标是？", "options": {"A": "73%", "B": "70%", "C": "72%", "D": "75%"}, "answer": "A", "explanation": "规划纲要提出养老机构护理型床位占比达到73%。"}, {"id": 152, "chapter": "时事政治", "stem": "“十五五”规划期末，每千人口执业（助理）医师数目标是？", "options": {"A": "3.5人", "B": "3.7人", "C": "4人", "D": "4.2人"}, "answer": "B", "explanation": "规划纲要提出每千人口执业（助理）医师数达到3.7人。"}, {"id": 153, "chapter": "时事政治", "stem": "“十五五”规划期末，每千人口注册护士数目标是？", "options": {"A": "4.8人", "B": "5人", "C": "5.1人", "D": "5.3人"}, "answer": "C", "explanation": "规划纲要提出每千人口注册护士数达到5.1人。"}, {"id": 154, "chapter": "时事政治", "stem": "“十五五”规划纲要对国内生产总值增长指标采用哪种设置方式？", "options": {"A": "五年统一确定一个刚性年均增速", "B": "只设2030年期末总量、不设年度要求", "C": "以各省增速加权值直接作为全国目标", "D": "保持在合理区间、各年度视情提出"}, "answer": "D", "explanation": "规划纲要注重保持合理增长速度，年度目标结合实际提出。"}, {"id": 155, "chapter": "时事政治", "stem": "到2035年，我国人均国内生产总值的目标表述是？", "options": {"A": "比2020年翻一番，达到中等发达国家水平", "B": "人均国内生产总值比2020年增长50%", "C": "经济总量和人均收入均达到高收入国家平均水平", "D": "人均国内生产总值达到发达国家中位水平"}, "answer": "A", "explanation": "规划纲要衔接2035年远景目标，提出人均国内生产总值比2020年翻一番、达到中等发达国家水平。"}, {"id": 156, "chapter": "时事政治", "stem": "2020年9月8日，全国抗击新冠肺炎疫情表彰大会在北京人民大会堂隆重举行。中共中央总书记、国家主席、中央军委主席习近平向“共和国勋章”获得者、“人民英雄“国家荣誉称号获得者颁授勋章奖章，下列不属于此次获奖者的是【 】。", "options": {"A": "钟南山", "B": "张伯礼", "C": "张定宇", "D": "张文宏"}, "answer": "D", "explanation": ""}, {"id": 157, "chapter": "时事政治", "stem": "“十五五”时期在基本实现社会主义现代化进程中的阶段定位是？", "options": {"A": "全面建成社会主义现代化强国的决胜时期", "B": "承前启后、夯实基础、全面发力的关键时期", "C": "基本实现社会主义现代化的收官时期", "D": "转变发展方式、优化经济结构的攻关时期"}, "answer": "B", "explanation": "规划纲要把“十五五”时期定位为基本实现社会主义现代化夯实基础、全面发力的关键时期。"}, {"id": 158, "chapter": "时事政治", "stem": "“十五五”规划前瞻布局未来产业时，明确提出推动研发应用的下一代移动通信技术是？", "options": {"A": "第五代移动通信增强技术", "B": "卫星互联网", "C": "第六代移动通信", "D": "工业互联网"}, "answer": "C", "explanation": "规划纲要提出前瞻布局第六代移动通信等未来产业。"}, {"id": 159, "chapter": "时事政治", "stem": "“十五五”规划前瞻布局未来产业时，明确列举的人机融合前沿方向是？", "options": {"A": "扩展现实交互", "B": "智能语音交互", "C": "数字孪生交互", "D": "脑机接口"}, "answer": "D", "explanation": "脑机接口是规划纲要部署的未来产业方向之一。"}, {"id": 160, "chapter": "时事政治", "stem": "“十五五”规划纲要由哪次会议批准？", "options": {"A": "十四届全国人大四次会议", "B": "党的二十届四中全会", "C": "十四届全国人大三次会议", "D": "全国政协十四届四次会议"}, "answer": "A", "explanation": "“十五五”规划纲要经十四届全国人大四次会议批准。"}, {"id": 161, "chapter": "时事政治", "stem": "设立台湾光复纪念日主要是为了纪念哪一历史事件？", "options": {"A": "《开罗宣言》发表", "B": "台湾光复、回归祖国", "C": "日本签署投降书", "D": "台湾省行政长官公署成立"}, "answer": "B", "explanation": "10月25日纪念1945年台湾光复、回归祖国。"}, {"id": 162, "chapter": "时事政治", "stem": "下列哪组数字与2026年宏观预期目标对应正确？", "options": {"A": "GDP增长5%左右、CPI涨幅1.5%左右", "B": "GDP增长4%左右、CPI涨幅2.5%左右", "C": "GDP增长4.5%—5%、CPI涨幅2%左右", "D": "GDP增长5%—5.5%、CPI涨幅3%左右"}, "answer": "C", "explanation": "政府工作报告分别提出GDP增长4.5%—5%和CPI涨幅2%左右。"}, {"id": 163, "chapter": "时事政治", "stem": "下列哪组2026年财政安排对应正确？", "options": {"A": "超长期特别国债1.5万亿元、地方专项债4万亿元", "B": "超长期特别国债1.3万亿元、地方专项债4.8万亿元", "C": "超长期特别国债2万亿元、地方专项债4.4万亿元", "D": "超长期特别国债1.3万亿元、地方专项债4.4万亿元"}, "answer": "D", "explanation": "两项安排分别为1.3万亿元和4.4万亿元。"}, {"id": 164, "chapter": "时事政治", "stem": "“十五五”规划的20项主要指标总体体现了什么取向？", "options": {"A": "兼顾经济发展、创新驱动、民生福祉、绿色低碳和安全保障", "B": "突出经济增速和投资规模，其他指标作为参考", "C": "以民生福祉和绿色低碳指标替代经济发展指标", "D": "主要衡量科技创新和安全保障，不再设置民生指标"}, "answer": "A", "explanation": "五方面指标体现高质量发展、创新、民生、绿色和安全的综合导向。"}, {"id": 165, "chapter": "时事政治", "stem": "第二届中国—中亚峰会期间，中国同中亚五国共同签署的首份以睦邻友好合作为主题的条约是？", "options": {"A": "《阿斯塔纳宣言》", "B": "永久睦邻友好合作条约", "C": "《中国—中亚峰会西安宣言》", "D": "中国—中亚元首会晤机制章程"}, "answer": "B", "explanation": "峰会期间，中国同中亚五国共同签署永久睦邻友好合作条约，这是六国关系发展中的重要政治成果。"}, {"id": 166, "chapter": "时事政治", "stem": "党的二十届四中全会提出制定“十五五”规划建议，主要遵循的根本指导思想是？", "options": {"A": "习近平经济思想", "B": "习近平新时代中国特色社会主义思想", "C": "总体国家安全观", "D": "马克思主义基本原理同中国具体实际相结合"}, "answer": "B", "explanation": "全会强调坚持以习近平新时代中国特色社会主义思想为指导。"}, {"id": 167, "chapter": "时事政治", "stem": "下列哪组“十五五”民生指标对应完全正确？", "options": {"A": "人均预期寿命79.5岁、劳动年龄人口平均受教育年限11.7年", "B": "人均预期寿命80岁、劳动年龄人口平均受教育年限11.5年", "C": "人均预期寿命80岁、劳动年龄人口平均受教育年限11.7年", "D": "人均预期寿命80.5岁、劳动年龄人口平均受教育年限12年"}, "answer": "C", "explanation": "两项规划期末目标分别为80岁和11.7年。"}, {"id": 168, "chapter": "时事政治", "stem": "下列哪组“十五五”医疗养老指标对应完全正确？", "options": {"A": "医师3.7人、护士5人、护理型床位占比75%", "B": "医师4人、护士5.1人、护理型床位占比72%", "C": "医师3.5人、护士5.3人、护理型床位占比70%", "D": "每千人口医师3.7人、注册护士5.1人、护理型床位占比73%"}, "answer": "D", "explanation": "规划纲要给出的三项期末目标依次为3.7人、5.1人和73%。"}, {"id": 169, "chapter": "时事政治", "stem": "下列哪组时间与事件对应完全正确？", "options": {"A": "2025年6月17日第二届中国—中亚峰会；10月20日至23日党的二十届四中全会", "B": "2025年6月16日第二届中国—中亚峰会；10月20日至23日党的二十届四中全会", "C": "2025年6月17日第二届中国—中亚峰会；9月20日至23日党的二十届四中全会", "D": "2025年6月18日第二届中国—中亚峰会；10月23日至26日党的二十届四中全会"}, "answer": "A", "explanation": "两项重大活动分别发生于2025年6月17日和10月20日至23日。"}, {"id": 170, "chapter": "时事政治", "stem": "结合2026年政府工作报告和预算报告，下列说法正确的是？", "options": {"A": "赤字率保持不变，主要依靠地方专项债扩大支出", "B": "积极财政政策通过赤字、特别国债和专项债等工具协同发力", "C": "超长期特别国债主要用于弥补地方经常性支出", "D": "中央预算内投资规模高于地方政府专项债规模"}, "answer": "B", "explanation": "2026年财政安排综合运用赤字、超长期特别国债和地方专项债等政策工具。"}, {"id": 171, "chapter": "\"四史\"学习", "stem": "下列哪一位是我国古代抗倭名将？【 】", "options": {"A": "袁崇焕", "B": "郑成功", "C": "戚继光", "D": "林则徐"}, "answer": "C", "explanation": ""}, {"id": 172, "chapter": "\"四史\"学习", "stem": "把毛泽东思想确立为党的指导思想的是哪次党代会？", "options": {"A": "党的六大", "B": "党的七届二中全会", "C": "党的七大", "D": "党的八大"}, "answer": "C", "explanation": "1945年党的七大把毛泽东思想确立为党的指导思想并写入党章。"}, {"id": 173, "chapter": "\"四史\"学习", "stem": "五四运动在中国近代革命史上的重要意义是？", "options": {"A": "标志中国旧民主主义革命转向社会主义革命", "B": "标志中国工人阶级开始独立领导全国革命", "C": "促进马克思主义传播并推动中国新民主主义革命发展", "D": "完成了马克思主义同中国工人运动的结合"}, "answer": "C", "explanation": "五四运动促进了马克思主义同中国工人运动相结合，是新民主主义革命的重要开端。"}, {"id": 174, "chapter": "\"四史\"学习", "stem": "贫穷落后的清政府成为列强宰割的对象，但英勇的中国人民从来没有向侵略者低头，近代中国人民自发抗击外国侵略的第一次英勇斗争是【 】。", "options": {"A": "虎门销烟", "B": "三元里人民抗英", "C": "义和团运动", "D": "南京事变"}, "answer": "B", "explanation": ""}, {"id": 175, "chapter": "\"四史\"学习", "stem": "辛亥革命的失败证明了【 】", "options": {"A": "帝国主义和反动军阀力量太强大", "B": "民族资产阶级不能领导中国民主革命取得彻底胜利", "C": "中国不能走西方民主议会道路", "D": "必须进行革命武装斗争"}, "answer": "B", "explanation": "辛亥革命由民族资产阶级领导，虽推翻帝制但未完成反帝反封建任务，其失败从根本上说明民族资产阶级的软弱性和妥协性，无法领导中国民主革命取得彻底胜利，A、C、D 是失败原因或启示，非核心证明结论。"}, {"id": 176, "chapter": "\"四史\"学习", "stem": "党的三大决定采取哪种方式实现国共合作？", "options": {"A": "以党对党方式建立联合组织", "B": "共产党员退出共产党后加入国民党", "C": "先建立军事同盟、暂缓政治合作", "D": "共产党员以个人身份加入国民党"}, "answer": "D", "explanation": "1923年党的三大决定共产党员以个人身份加入国民党，实现党内合作。"}, {"id": 177, "chapter": "\"四史\"学习", "stem": "“雄关漫道真如铁，而今迈步从头越。”写于遵义会议后，对毛泽东这一词句的理解，最贴近其历史寓意的是【 】", "options": {"A": "遵义会议后，红军长征取得了胜利", "B": "遵义会议，是中国革命生死攸关的转折点", "C": "遵义会议前的中国革命彻底失败，必须从头再来", "D": "革命道路漫长而艰巨，前途不容乐观"}, "answer": "B", "explanation": ""}, {"id": 178, "chapter": "\"四史\"学习", "stem": "毛泽东提出人民抗战路线的主要依据是【 】。", "options": {"A": "国民党正面战场失利", "B": "抗日战争是正义的反侵略战争", "C": "战争力量之最深厚的根源在民众之中", "D": "敌强我弱不能迅速战胜日本"}, "answer": "C", "explanation": ""}, {"id": 179, "chapter": "\"四史\"学习", "stem": "八七会议确定的总方针是？", "options": {"A": "土地革命和武装反抗国民党反动派", "B": "建立抗日民族统一战线并停止内战", "C": "以城市暴动为中心夺取全国政权", "D": "开展根据地政权建设和土地改革"}, "answer": "A", "explanation": "八七会议确定实行土地革命和武装起义的方针。"}, {"id": 180, "chapter": "\"四史\"学习", "stem": "毛泽东1963年发表“向雷锋同志学习”的题词。雷锋纪念日是【 】？", "options": {"A": "3月2日", "B": "3月3日", "C": "3月4日", "D": "3月5日"}, "answer": "D", "explanation": ""}, {"id": 181, "chapter": "\"四史\"学习", "stem": "1931-1936年，中国抗日民主运动的特点是【 】。①既有自发的群众斗争，又有国民党内爱国将领的斗争②抗日与反蒋和逼蒋相结合③都有共产党的领导④都被日军直接镇压", "options": {"A": "①②③④", "B": "③④", "C": "①②④", "D": "①②"}, "answer": "D", "explanation": ""}, {"id": 182, "chapter": "\"四史\"学习", "stem": "三湾改编最重要的组织制度创新之一是？", "options": {"A": "实行营、团两级党委制", "B": "把党支部建在连上", "C": "确立政治委员拥有军事最终决定权", "D": "把党的委员会建在营以上单位"}, "answer": "B", "explanation": "三湾改编确立支部建在连上的原则，加强党对军队的领导。"}, {"id": 183, "chapter": "\"四史\"学习", "stem": "下列不属于八路军、新四军建立的敌后根据地的是【 】。", "options": {"A": "湘赣", "B": "晋察冀", "C": "陕甘宁", "D": "晋绥"}, "answer": "A", "explanation": "湘赣革命根据地，是土地革命战争时期，在井冈山、赣西南、湘东南地区革命斗争基础上，于1930年2月至1934年8月建立发展起来的。"}, {"id": 184, "chapter": "\"四史\"学习", "stem": "1894年日本发动甲午战争，翌年清政府战败，于4月17日被迫签订丧权辱国的【 】，把台湾割让日本。从此台湾沦为日本的殖民地达50年之久。", "options": {"A": "《马关条约》", "B": "《南京条约》", "C": "《北京条约》", "D": "《辛丑条约》"}, "answer": "A", "explanation": ""}, {"id": 185, "chapter": "\"四史\"学习", "stem": "古田会议确立的人民军队建设根本原则是？", "options": {"A": "党指挥枪、官兵平等", "B": "支部建在连上、士兵委员会参与管理", "C": "思想建党、政治建军", "D": "政治工作服从单纯军事需要"}, "answer": "C", "explanation": "1929年古田会议确立思想建党、政治建军原则。"}, {"id": 186, "chapter": "\"四史\"学习", "stem": "1662年，民族英雄郑成功从【 】殖民者手中收复了中国领土台湾。", "options": {"A": "日本", "B": "荷兰", "C": "菲律宾", "D": "葡萄牙"}, "answer": "B", "explanation": ""}, {"id": 187, "chapter": "\"四史\"学习", "stem": "遵义会议集中解决了当时最迫切的什么问题？", "options": {"A": "政治路线和思想路线问题", "B": "土地政策和根据地建设问题", "C": "抗日民族统一战线策略问题", "D": "军事和组织问题"}, "answer": "D", "explanation": "遵义会议着重解决了当时具有决定意义的军事和组织问题。"}, {"id": 188, "chapter": "\"四史\"学习", "stem": "抗日战争中，打破了日本侵略者“三个月灭亡中国”狂言的著名战役是【 】。", "options": {"A": "太原会战", "B": "淞沪会战", "C": "武汉会战", "D": "桂柳会战"}, "answer": "B", "explanation": ""}, {"id": 189, "chapter": "\"四史\"学习", "stem": "新四军的首任军长是【 】", "options": {"A": "项英", "B": "贺龙", "C": "叶挺", "D": "林彪"}, "answer": "C", "explanation": "叶挺，著名军事家、政治家，参与指挥南昌起义并出任前敌总指挥，参加广州起义时任起义军工农红军总司令，抗日战争中又出任新四军首任军长。"}, {"id": 190, "chapter": "\"四史\"学习", "stem": "西安事变和平解决的历史作用是？", "options": {"A": "成为扭转时局的枢纽，促进抗日民族统一战线形成", "B": "结束十年内战并立即实现国共全面合作", "C": "标志抗日民族统一战线正式建立", "D": "促使国民政府正式对日宣战"}, "answer": "A", "explanation": "西安事变和平解决为停止内战、共同抗日创造了条件。"}, {"id": 191, "chapter": "\"四史\"学习", "stem": "为了纪念一位在上海长期从事党的秘密工作的共产党员，曾以他为主要原型拍摄了电影故事片《永不消逝的电波》。这位革命烈士是：【 】", "options": {"A": "瞿秋白", "B": "李汉俊", "C": "马本斋", "D": "李白"}, "answer": "D", "explanation": "舞剧《永不消逝的电波》以改编自抗日战争和解放时期的共产党上海地下电台的发报员李白的真实故事为素材，在真实史料的基础之上进行再创作。以李白潜伏在沦陷区冒着生命危险向延安根据地发电报的传奇故事，来激励当代人向革命先烈致敬，演绎白色恐怖下共产党的坚定毅力，宣扬人性光辉。"}, {"id": 192, "chapter": "\"四史\"学习", "stem": "解放战争时期，使晋察冀和晋冀鲁豫解放区连成一片的军事行动是【 】", "options": {"A": "解放石家庄", "B": "千里跃进大别山", "C": "收复延安", "D": "发动平津战役"}, "answer": "A", "explanation": "解放石家庄战役是人民解放军“夺取大城市之创例”，为我军适应战局变化的形势，由运动战转向攻坚战，提供了攻克国民党坚固设防的大城市的战术经验。"}, {"id": 193, "chapter": "\"四史\"学习", "stem": "全国性抗日战争开始的标志是？", "options": {"A": "九一八事变", "B": "七七事变", "C": "一二·九运动", "D": "八一三事变"}, "answer": "B", "explanation": "1937年7月7日卢沟桥事变爆发，标志全国性抗日战争开始。"}, {"id": 194, "chapter": "\"四史\"学习", "stem": "中央苏区第五次“反围剿”失利，中央红军于1934年10开始长征，其间长征共通过【 】个省份？", "options": {"A": "8", "B": "10", "C": "12", "D": "14"}, "answer": "D", "explanation": ""}, {"id": 195, "chapter": "\"四史\"学习", "stem": "1937年9月，八路军第一一五师在【 】 伏击侵华日军，取得抗战以来的首次大捷，粉碎了日军”不可战胜”的神话，极大地鼓舞了全国人民的抗战信心。", "options": {"A": "平型关", "B": "娘子关", "C": "忻口", "D": "太原"}, "answer": "A", "explanation": ""}, {"id": 196, "chapter": "\"四史\"学习", "stem": "抗日战争时期，中国共产党在敌后战场实行的基本作战形式是？", "options": {"A": "运动战", "B": "阵地战", "C": "游击战争", "D": "破袭战"}, "answer": "C", "explanation": "党领导的敌后抗日根据地广泛开展游击战争，并与有利条件下的运动战相结合。"}, {"id": 197, "chapter": "\"四史\"学习", "stem": "“一条大河波浪宽，风吹稻花香两岸，我家就在岸上住，听惯了艄公的号子，看惯了船上的白帆。”这首歌充分表达了战士热爱祖国的强烈情感。这是电影【 】的插曲。", "options": {"A": "地道战", "B": "平原游击队", "C": "上甘岭", "D": "高山下的花环"}, "answer": "C", "explanation": "电影《上甘岭》讲述了上甘岭战役中，志愿军某部八连，在连长张忠发的率领下坚守阵地，与敌人浴血奋战，最终取得胜利的故事。"}, {"id": 198, "chapter": "\"四史\"学习", "stem": "党的七届二中全会提出，革命胜利后党的工作重心应当？", "options": {"A": "由乡村转移到城市", "B": "由城市转移到乡村", "C": "由军事斗争转移到外交斗争", "D": "由新民主主义革命转移到社会主义建设"}, "answer": "A", "explanation": "会议提出党的工作重心必须由乡村转移到城市。"}, {"id": 199, "chapter": "\"四史\"学习", "stem": "1937年8月22日至25日，中共中央召开著名的洛川会议，通过了【 】，提出了全面抗战路线。", "options": {"A": "《抗日救国告全体同胞书》", "B": "《中共中央为公布国共合作宣言》", "C": "《抗日救国十大纲领》", "D": "《中国共产党在抗日时期的任务》"}, "answer": "C", "explanation": ""}, {"id": 200, "chapter": "\"四史\"学习", "stem": "1940年，为打破日军的“囚笼政策”，八路军先后投入了【 】个团，发起百团大战，给日本侵略军以沉重的打击。", "options": {"A": "100", "B": "105", "C": "110", "D": "115"}, "answer": "B", "explanation": "百团大战，是抗日战争时期，八路军在华北敌后发动的一次大规模进攻和反“扫荡”的战役，由于参战兵力达105个团 ，故称“百团大战”。百团大战是抗日战争相持阶段八路军在华北地区发动的一次规模最大、持续时间最长的战役。"}, {"id": 201, "chapter": "\"四史\"学习", "stem": "1949年中国人民政治协商会议第一届全体会议通过的临时宪法性质文件是？", "options": {"A": "《中华苏维埃共和国宪法大纲》", "B": "《中国人民政治协商会议共同纲领》", "C": "《中华人民共和国宪法》", "D": "《中央人民政府组织法》"}, "answer": "B", "explanation": "《共同纲领》在新中国成立初期起了临时宪法作用。"}, {"id": 202, "chapter": "\"四史\"学习", "stem": "《中国共产党章程》中，党执政后的最大危险是【 】", "options": {"A": "脱离群众", "B": "背离马克思主义", "C": "外国的阴谋颠覆", "D": "放弃共产主义理想"}, "answer": "A", "explanation": ""}, {"id": 203, "chapter": "\"四史\"学习", "stem": "延安整风运动的方针是【 】。", "options": {"A": "惩前毖后，治病救人", "B": "批评与自我批评", "C": "有则改之，无则加勉", "D": "实事求是，团结和谐"}, "answer": "A", "explanation": ""}, {"id": 204, "chapter": "\"四史\"学习", "stem": "党的十一届三中全会作出的战略决策是？", "options": {"A": "把党和国家工作中心转移到经济建设上来、实行改革开放", "B": "确立社会主义市场经济体制改革目标", "C": "实行以城市经济体制改革为重点的全面改革", "D": "把改革重点转向政治体制并暂缓经济建设"}, "answer": "A", "explanation": "会议实现工作重心的战略转移，作出改革开放的历史性决策。"}, {"id": 205, "chapter": "\"四史\"学习", "stem": "1942年5月，在太行区反“扫荡”和保卫八路军总部的战斗中，八路军副参谋长【 】英勇牺牲。", "options": {"A": "左权", "B": "周子昆", "C": "袁国平", "D": "彭雪枫"}, "answer": "A", "explanation": ""}, {"id": 206, "chapter": "\"四史\"学习", "stem": "以下哪句毛泽东的诗句描写的是井冈山革命根据地的武装斗争【 】。", "options": {"A": "不到长城非好汉，屈指行程二万。", "B": "踏遍青山人未老，风景这边独好。", "C": "虎踞龙盘今胜昔，天翻地覆慨而慷。", "D": "早已森严壁垒，更加众志成城。"}, "answer": "D", "explanation": "选项A、B、C分别为为毛主席翻越六盘山、在会昌登山、人民解放军占领南京后的咏怀之作。"}, {"id": 207, "chapter": "\"四史\"学习", "stem": "安徽凤阳小岗村的改革探索主要体现在哪一方面？", "options": {"A": "人民公社体制改革", "B": "家庭联产承包责任制", "C": "城市国有企业承包经营责任制", "D": "农村土地所有权私有化"}, "answer": "B", "explanation": "小岗村“大包干”成为农村家庭联产承包责任制探索的重要标志。"}, {"id": 208, "chapter": "\"四史\"学习", "stem": "1936年6月，美国记者埃德加·斯诺访问陕北，并根据对毛泽东、周恩来、朱德等中共领导人和红军将士进行的访谈，撰成【 】一书，第一次向外界详细介绍了中国共产党和红军的事迹，对中国国内和世界产生了重大影响。", "options": {"A": "《来自红色中国的报道》", "B": "《中国未完成的革命》", "C": "《西行漫记》", "D": "《红色中国的挑战》"}, "answer": "C", "explanation": ""}, {"id": 209, "chapter": "\"四史\"学习", "stem": "中国共产党在抗日战争时期于敌后开创的第一个抗日根据地是【 】，也是当时各敌后根据地建设的模范。", "options": {"A": "晋西北抗日根据地", "B": "晋察冀抗日根据地", "C": "太行山抗日根据地", "D": "陕甘宁抗日根据地"}, "answer": "B", "explanation": ""}, {"id": 210, "chapter": "\"四史\"学习", "stem": "党的十二大提出的重大命题是？", "options": {"A": "社会主义初级阶段理论", "B": "改革开放是决定当代中国命运的关键一招", "C": "建设有中国特色的社会主义", "D": "建立社会主义市场经济体制"}, "answer": "C", "explanation": "1982年党的十二大明确提出走自己的道路，建设有中国特色的社会主义。"}, {"id": 211, "chapter": "\"四史\"学习", "stem": "党的十四大明确提出我国经济体制改革的目标是？", "options": {"A": "建立有计划的商品经济体制", "B": "实行计划经济与市场调节相结合", "C": "建立现代企业制度", "D": "建立社会主义市场经济体制"}, "answer": "D", "explanation": "1992年党的十四大明确建立社会主义市场经济体制的改革目标。"}, {"id": 212, "chapter": "\"四史\"学习", "stem": "第一次国共合作正式形成的标志是？", "options": {"A": "中国国民党第一次全国代表大会召开", "B": "中国共产党第三次全国代表大会召开", "C": "孙中山发表《中国国民党宣言》", "D": "黄埔军校正式成立"}, "answer": "A", "explanation": "1924年国民党一大召开，标志第一次国共合作正式形成。"}, {"id": 213, "chapter": "\"四史\"学习", "stem": "瓦窑堡会议解决的主要战略问题是？", "options": {"A": "推动国共第二次合作正式形成", "B": "确定全面抗战路线和持久战方针", "C": "建立抗日民族统一战线", "D": "纠正党内'左'倾教条主义错误"}, "answer": "C", "explanation": "1935年瓦窑堡会议确定建立最广泛的抗日民族统一战线的策略方针。"}, {"id": 214, "chapter": "\"四史\"学习", "stem": "延安整风运动反对的三种不良作风是？", "options": {"A": "主观主义、官僚主义、党八股", "B": "教条主义、宗派主义、形式主义", "C": "主观主义、自由主义、官僚主义", "D": "主观主义、宗派主义、党八股"}, "answer": "D", "explanation": "延安整风反对主观主义以整顿学风、宗派主义以整顿党风、党八股以整顿文风。"}, {"id": 215, "chapter": "\"四史\"学习", "stem": "1956年社会主义改造基本完成，标志着我国？", "options": {"A": "社会主义基本制度建立", "B": "新民主主义社会制度建立", "C": "社会主义工业化任务完成", "D": "社会主义市场经济体制初步建立"}, "answer": "A", "explanation": "社会主义改造基本完成，社会主义基本制度在我国建立起来。"}, {"id": 216, "chapter": "\"四史\"学习", "stem": "党的十三大系统阐述了哪一理论？", "options": {"A": "社会主义市场经济理论", "B": "社会主义初级阶段理论", "C": "中国特色社会主义理论体系", "D": "党在社会主义初级阶段的基本路线"}, "answer": "B", "explanation": "1987年党的十三大系统阐述社会主义初级阶段理论和基本路线。"}, {"id": 217, "chapter": "\"四史\"学习", "stem": "1992年邓小平南方谈话重点回答的核心问题是？", "options": {"A": "计划与市场是不是社会主义和资本主义的本质区别", "B": "改革开放是否必须坚持四项基本原则", "C": "什么是社会主义、怎样建设社会主义", "D": "怎样建立社会主义市场经济的基本框架"}, "answer": "C", "explanation": "南方谈话围绕社会主义本质和改革发展的一系列重大问题作出深刻回答。"}, {"id": 218, "chapter": "\"四史\"学习", "stem": "世界上第一个无产阶级政权是？", "options": {"A": "第一国际", "B": "苏维埃俄国", "C": "共产主义者同盟", "D": "巴黎公社"}, "answer": "D", "explanation": "1871年建立的巴黎公社是无产阶级建立政权的第一次伟大尝试。"}, {"id": 219, "chapter": "\"四史\"学习", "stem": "下列改革开放事件按时间先后排列正确的是？", "options": {"A": "十一届三中全会—党的十二大—设立经济特区—邓小平南方谈话", "B": "设立经济特区—十一届三中全会—党的十二大—邓小平南方谈话", "C": "十一届三中全会—设立经济特区—党的十二大—邓小平南方谈话", "D": "十一届三中全会—设立经济特区—邓小平南方谈话—党的十二大"}, "answer": "C", "explanation": "四项事件分别发生于1978年、1980年、1982年和1992年。"}, {"id": 220, "chapter": "\"四史\"学习", "stem": "下列关于社会主义发展史的表述正确的是？", "options": {"A": "巴黎公社第一次使社会主义由理论变为现实，十月革命建立首个无产阶级政权", "B": "《资本论》第一卷标志马克思主义公开问世，十月革命发生于1871年", "C": "空想社会主义创立了科学社会主义理论，巴黎公社建立了首个社会主义国家", "D": "《共产党宣言》标志马克思主义公开问世，十月革命把社会主义从理论变为现实"}, "answer": "D", "explanation": "马克思、恩格斯创立科学社会主义；1848年《共产党宣言》发表；1917年十月革命建立世界上第一个社会主义国家。"}, {"id": 221, "chapter": "科学家精神", "stem": "勇攀高峰、敢为人先主要体现科学家精神中的？", "options": {"A": "求实精神", "B": "创新精神", "C": "奉献精神", "D": "协同精神"}, "answer": "B", "explanation": "勇攀高峰、敢为人先对应创新精神。"}, {"id": 222, "chapter": "科学家精神", "stem": "追求真理、严谨治学主要体现科学家精神中的？", "options": {"A": "创新精神", "B": "协同精神", "C": "求实精神", "D": "育人精神"}, "answer": "C", "explanation": "追求真理、严谨治学对应求实精神。"}, {"id": 223, "chapter": "科学家精神", "stem": "淡泊名利、潜心研究主要体现科学家精神中的？", "options": {"A": "爱国精神", "B": "求实精神", "C": "协同精神", "D": "奉献精神"}, "answer": "D", "explanation": "淡泊名利、潜心研究对应奉献精神。"}, {"id": 224, "chapter": "科学家精神", "stem": "集智攻关、团结协作主要体现科学家精神中的？", "options": {"A": "协同精神", "B": "创新精神", "C": "求实精神", "D": "育人精神"}, "answer": "A", "explanation": "集智攻关、团结协作对应协同精神。"}, {"id": 225, "chapter": "科学家精神", "stem": "甘为人梯、奖掖后学主要体现科学家精神中的？", "options": {"A": "奉献精神", "B": "育人精神", "C": "协同精神", "D": "爱国精神"}, "answer": "B", "explanation": "甘为人梯、奖掖后学对应育人精神。"}, {"id": 226, "chapter": "科学家精神", "stem": "钱学森最具代表性的事业领域是？", "options": {"A": "原子能科学", "B": "人造卫星总体设计", "C": "航天与导弹技术", "D": "核潜艇总体设计"}, "answer": "C", "explanation": "钱学森是我国航天事业的重要奠基人。"}, {"id": 227, "chapter": "科学家精神", "stem": "邓稼先为我国哪项事业作出了突出贡献？", "options": {"A": "原子能基础研究", "B": "核潜艇总体设计", "C": "导弹总体设计", "D": "核武器研制"}, "answer": "D", "explanation": "邓稼先长期领导核武器理论研究和设计工作。"}, {"id": 228, "chapter": "科学家精神", "stem": "中办、国办印发《关于进一步弘扬科学家精神加强作风和学风建设的意见》是在？", "options": {"A": "2019年", "B": "2017年", "C": "2018年", "D": "2021年"}, "answer": "A", "explanation": "该意见于2019年印发。"}, {"id": 229, "chapter": "科学家精神", "stem": "中国第一艘航空母舰是辽宁舰，请问它的总设计师是下列哪位科学家？【 】", "options": {"A": "朱英富", "B": "王硕威", "C": "黄旭华", "D": "吴晓光"}, "answer": "A", "explanation": ""}, {"id": 230, "chapter": "科学家精神", "stem": "钱三强最具代表性的科技贡献领域是？", "options": {"A": "核武器理论设计", "B": "核潜艇动力工程", "C": "原子能科学", "D": "人造卫星总体设计"}, "answer": "C", "explanation": "钱三强是我国原子能科学事业的重要奠基人。"}, {"id": 231, "chapter": "科学家精神", "stem": "赵九章最具代表性的学科与事业领域是？", "options": {"A": "核物理与原子能科学", "B": "空气动力学与航空工程", "C": "射电天文学与天文工程", "D": "地球物理与空间科学"}, "answer": "D", "explanation": "赵九章是著名地球物理学家，也是我国人造卫星事业的倡导者和奠基人之一。"}, {"id": 232, "chapter": "科学家精神", "stem": "黄旭华院士为了给参加深潜试验的官兵增加信心，亲自下艇参与了多少米深度的极限深潜试验？", "options": {"A": "100米", "B": "250米", "C": "300米", "D": "500米"}, "answer": "C", "explanation": "1988年，一艘新型核潜艇正在南海进行极限深潜试验。这次试验的目标就是要挑战300米的极限深度。为了稳定军心，已经60多岁的总设计师黄旭华院士，不顾个人安危，坚持亲自下艇，与官兵们一同下潜至300米的极限深度。"}, {"id": 233, "chapter": "科学家精神", "stem": "郭永怀是下列哪项国家事业的功勋科学家？", "options": {"A": "“两弹一星”", "B": "载人航天工程", "C": "核潜艇工程", "D": "杂交水稻育种"}, "answer": "A", "explanation": "郭永怀为我国核武器、导弹和卫星事业作出重要贡献。"}, {"id": 234, "chapter": "科学家精神", "stem": "1999年共有多少位科技专家获授或追授“两弹一星”功勋奖章？", "options": {"A": "21位", "B": "23位", "C": "24位", "D": "26位"}, "answer": "B", "explanation": "1999年国家授予、追授23位科技专家“两弹一星”功勋奖章。"}, {"id": 235, "chapter": "科学家精神", "stem": "中国的导弹之父是谁？【 】", "options": {"A": "钱学森", "B": "钱三强", "C": "朱光亚", "D": "邓稼先"}, "answer": "A", "explanation": "交大著名校友钱学森在空气动力学，火箭及导弹研究，航空航天科学技术等方面的成就享誉世界，为我国航空航天技术的发展做出巨大贡献。"}, {"id": 236, "chapter": "科学家精神", "stem": "于敏最突出的科技贡献是？", "options": {"A": "原子弹理论设计", "B": "核潜艇动力设计", "C": "氢弹理论和设计", "D": "导弹制导系统设计"}, "answer": "C", "explanation": "于敏为我国氢弹原理突破和武器化作出重大贡献。"}, {"id": 237, "chapter": "科学家精神", "stem": "请问歼八飞机型号总设计师是下列哪位科学家？【 】", "options": {"A": "顾诵芬", "B": "吴光辉", "C": "朱英富", "D": "孙聪"}, "answer": "A", "explanation": ""}, {"id": 238, "chapter": "科学家精神", "stem": "孙家栋最具代表性的科技领域是？", "options": {"A": "载人航天与空间站工程", "B": "运载火箭总体设计", "C": "空气动力学与飞行器设计", "D": "人造卫星与深空探测"}, "answer": "D", "explanation": "孙家栋是我国卫星、深空探测和卫星导航事业的重要开创者之一。"}, {"id": 239, "chapter": "科学家精神", "stem": "被誉为“稀土之父”的徐光宪学长，在哪一年获得了国家最高科学技术奖？", "options": {"A": "1951年", "B": "2008年", "C": "2009年", "D": "2012年"}, "answer": "B", "explanation": "徐光宪院士是2008年度国家最高科学技术奖得主。"}, {"id": 240, "chapter": "科学家精神", "stem": "被誉为“中国天眼”的重大科技设施是？", "options": {"A": "500米口径球面射电望远镜FAST", "B": "郭守敬望远镜LAMOST", "C": "高海拔宇宙线观测站LHAASO", "D": "中国散裂中子源CSNS"}, "answer": "A", "explanation": "FAST是500米口径球面射电望远镜，被誉为“中国天眼”。"}, {"id": 241, "chapter": "科学家精神", "stem": "黄旭华毕生投入的国家重大工程是？", "options": {"A": "航空母舰总体设计", "B": "核潜艇研制", "C": "核武器理论设计", "D": "人造卫星总体设计"}, "answer": "B", "explanation": "黄旭华是我国第一代核潜艇总设计师。"}, {"id": 242, "chapter": "科学家精神", "stem": "屠呦呦的代表性科研成果是？", "options": {"A": "人工合成牛胰岛素", "B": "全反式维甲酸", "C": "青蒿素", "D": "高效价脊髓灰质炎疫苗"}, "answer": "C", "explanation": "屠呦呦团队发现青蒿素，为疟疾治疗作出突出贡献。"}, {"id": 243, "chapter": "科学家精神", "stem": "下列哪组完整列出了科学家精神的六个方面？", "options": {"A": "爱国、创新、求实、奉献、协同、育人", "B": "爱国、创新、严谨、奉献、开放、育人", "C": "爱国、求真、创新、协作、诚信、传承", "D": "报国、创新、求实、淡泊、合作、担当"}, "answer": "A", "explanation": "官方概括的六个方面为爱国、创新、求实、奉献、协同、育人。"}, {"id": 244, "chapter": "科学家精神", "stem": "科研人员如实记录实验失败结果，最直接体现哪种科学家精神？", "options": {"A": "创新精神", "B": "求实精神", "C": "奉献精神", "D": "协同精神"}, "answer": "B", "explanation": "尊重事实、严谨记录属于追求真理、严谨治学的求实精神。"}, {"id": 245, "chapter": "科学家精神", "stem": "跨学科团队共享数据、共同攻克关键技术，最直接体现？", "options": {"A": "求实精神", "B": "创新精神", "C": "协同精神", "D": "育人精神"}, "answer": "C", "explanation": "集智攻关、团结协作是协同精神的典型表现。"}, {"id": 246, "chapter": "科学家精神", "stem": "钱学森于哪一年回到祖国？", "options": {"A": "1955年", "B": "1950年", "C": "1956年", "D": "1960年"}, "answer": "A", "explanation": "钱学森于1955年回国，投身新中国国防科技和航天事业。"}, {"id": 247, "chapter": "科学家精神", "stem": "邓稼先参与并领导的核心工作是？", "options": {"A": "核反应堆物理研究", "B": "核武器理论设计", "C": "导弹总体与制导设计", "D": "核潜艇动力装置研制"}, "answer": "B", "explanation": "邓稼先是我国核武器理论研究和设计的主要组织者、领导者之一。"}, {"id": 248, "chapter": "科学家精神", "stem": "钱三强主持和推动的事业被称为我国哪一科学事业的重要源头？", "options": {"A": "核武器研制事业", "B": "人造卫星事业", "C": "原子能科学事业", "D": "高能加速器事业"}, "answer": "C", "explanation": "钱三强为我国原子能研究机构建设和人才培养作出奠基性贡献。"}, {"id": 249, "chapter": "科学家精神", "stem": "郭永怀在飞机失事后仍设法保护重要资料，这一事迹最突出体现了？", "options": {"A": "尊重事实、严谨治学", "B": "集智攻关、团结协作", "C": "甘为人梯、奖掖后学", "D": "以身许国、忠于使命"}, "answer": "D", "explanation": "郭永怀在生命最后时刻保护重要科研资料，体现了崇高的爱国奉献精神。"}, {"id": 250, "chapter": "科学家精神", "stem": "在2014年被授予国家最高科学技术奖，被称为我国“氢弹／中子弹之父”的是著名科学家【 】。", "options": {"A": "于敏", "B": "孙健初", "C": "邓国顺", "D": "钱学森"}, "answer": "A", "explanation": ""}, {"id": 251, "chapter": "科学家精神", "stem": "郭永怀在“两弹一星”功勋奖章获得者中具有哪一特殊身份？", "options": {"A": "唯一以烈士身份获得该奖章者", "B": "唯一在国外出生的获奖者", "C": "唯一同时获得国家最高科技奖者", "D": "唯一从事空气动力学研究者"}, "answer": "A", "explanation": "郭永怀是23位“两弹一星”功勋奖章获得者中唯一的烈士。"}, {"id": 252, "chapter": "科学家精神", "stem": "于敏长期隐姓埋名从事的核心任务是？", "options": {"A": "原子弹中子物理研究", "B": "氢弹理论研究", "C": "核潜艇动力研究", "D": "导弹再入技术研究"}, "answer": "B", "explanation": "于敏长期从事核武器特别是氢弹理论研究。"}, {"id": 253, "chapter": "科学家精神", "stem": "孙家栋在“东方红一号”研制中担任的重要职责是？", "options": {"A": "技术负责人", "B": "副总设计师", "C": "卫星总体组组长", "D": "总体设计负责人"}, "answer": "D", "explanation": "钱学森任命孙家栋为我国第一颗人造地球卫星总体设计负责人。"}, {"id": 254, "chapter": "科学家精神", "stem": "南仁东在FAST工程中担任的主要职务是？", "options": {"A": "首席科学家兼总工程师", "B": "工程总指挥兼首席科学家", "C": "台址勘察负责人兼观测站站长", "D": "项目学术委员会主任兼总设计师"}, "answer": "A", "explanation": "南仁东是FAST工程的发起者和奠基人，并任首席科学家兼总工程师。"}, {"id": 255, "chapter": "科学家精神", "stem": "FAST口径为多少米？", "options": {"A": "300米", "B": "500米", "C": "520米", "D": "600米"}, "answer": "B", "explanation": "FAST全称为500米口径球面射电望远镜。"}, {"id": 256, "chapter": "科学家精神", "stem": "屠呦呦因发现青蒿素于哪一年获得诺贝尔奖？", "options": {"A": "2011年", "B": "2014年", "C": "2015年", "D": "2016年"}, "answer": "C", "explanation": "屠呦呦获得2015年诺贝尔生理学或医学奖。"}, {"id": 257, "chapter": "科学家精神", "stem": "屠呦呦获得的是诺贝尔哪一奖项？", "options": {"A": "物理学奖", "B": "化学奖", "C": "和平奖", "D": "生理学或医学奖"}, "answer": "D", "explanation": "其获奖类别为诺贝尔生理学或医学奖。"}, {"id": 258, "chapter": "科学家精神", "stem": "袁隆平创建的代表性技术体系是？", "options": {"A": "超级杂交稻技术体系", "B": "矮秆育种技术体系", "C": "单倍体育种技术体系", "D": "分子标记辅助育种体系"}, "answer": "A", "explanation": "袁隆平发明三系法、发展两系法并创建超级杂交稻技术体系。"}, {"id": 259, "chapter": "科学家精神", "stem": "吴文俊开创的研究方向是？", "options": {"A": "计算机辅助几何证明", "B": "数学机械化", "C": "有限单元方法", "D": "代数拓扑分类"}, "answer": "B", "explanation": "吴文俊在拓扑学取得重要成果，并开创数学机械化新领域。"}, {"id": 260, "chapter": "科学家精神", "stem": "吴文俊与哪位科学家共同获得首届国家最高科学技术奖？", "options": {"A": "黄昆", "B": "王选", "C": "袁隆平", "D": "刘东生"}, "answer": "C", "explanation": "2000年度首届国家最高科学技术奖授予吴文俊和袁隆平。"}, {"id": 261, "chapter": "科学家精神", "stem": "徐光宪最具代表性的科技贡献是？", "options": {"A": "建立稀土离子交换色谱分离流程", "B": "创立稀土氯化焙烧分离工艺", "C": "发明稀土金属电解精炼方法", "D": "建立稀土串级萃取理论"}, "answer": "D", "explanation": "徐光宪建立串级萃取理论，推动我国稀土分离技术发展。"}, {"id": 262, "chapter": "科学家精神", "stem": "王振义治疗急性早幼粒细胞白血病的重要创新是？", "options": {"A": "用全反式维甲酸诱导恶性细胞分化", "B": "采用三氧化二砷诱导白血病细胞凋亡", "C": "采用大剂量联合化疗优先清除白血病细胞", "D": "通过造血干细胞移植重建正常造血系统"}, "answer": "A", "explanation": "王振义建立诱导分化治疗策略，使恶性早幼粒细胞向良性细胞分化。"}, {"id": 263, "chapter": "科学家精神", "stem": "顾诵芬为解决歼-8飞行抖振问题采取的关键做法是？", "options": {"A": "加装机载传感器进行遥测", "B": "乘坐伴飞飞机近距离观察", "C": "通过加密风洞测压数据单独反演抖振原因", "D": "根据试飞员报告调整机翼结构参数"}, "answer": "B", "explanation": "顾诵芬多次乘歼教-6伴飞近距观察，帮助找到并解决抖振问题。"}, {"id": 264, "chapter": "科学家精神", "stem": "中国航天“四老”是指哪一组科学家？", "options": {"A": "任新民、钱学森、黄纬禄、屠守锷", "B": "任新民、黄纬禄、梁守槃、孙家栋", "C": "钱学森、郭永怀、屠守锷、梁守槃", "D": "任新民、黄纬禄、屠守锷、梁守槃"}, "answer": "D", "explanation": "任新民、黄纬禄、屠守锷、梁守槃并称中国航天“四老”。"}, {"id": 265, "chapter": "科学家精神", "stem": "南仁东从提出FAST工程构想到望远镜落成，前后历时约多少年？", "options": {"A": "22年", "B": "18年", "C": "24年", "D": "28年"}, "answer": "A", "explanation": "南仁东团队从提出构想到选址建设，历时约22年推动FAST落成。"}, {"id": 266, "chapter": "科学家精神", "stem": "在2019年国家勋章和国家荣誉称号中，南仁东获授的称号是？", "options": {"A": "共和国勋章", "B": "人民科学家", "C": "改革先锋", "D": "人民教育家"}, "answer": "B", "explanation": "南仁东被授予“人民科学家”国家荣誉称号。"}, {"id": 267, "chapter": "科学家精神", "stem": "下列科学家与贡献对应完全正确的是？", "options": {"A": "钱学森—航天；邓稼先—核潜艇；黄旭华—核武器；南仁东—FAST", "B": "钱学森—原子能；邓稼先—核武器；黄旭华—FAST；南仁东—核潜艇", "C": "钱学森—航天；邓稼先—核武器；黄旭华—核潜艇；南仁东—FAST", "D": "钱学森—航天；邓稼先—FAST；黄旭华—核潜艇；南仁东—人造卫星"}, "answer": "C", "explanation": "四位科学家的代表性贡献依次对应航天、核武器、核潜艇和FAST。"}, {"id": 268, "chapter": "科学家精神", "stem": "下列国家科技荣誉对应正确的是？", "options": {"A": "于敏—2009年度国家最高科学技术奖；孙家栋—2014年度国家最高科学技术奖", "B": "于敏—2014年度国家最高科学技术奖；孙家栋—2010年度国家最高科学技术奖", "C": "于敏—2016年度国家最高科学技术奖；孙家栋—2009年度国家最高科学技术奖", "D": "于敏—2014年度国家最高科学技术奖；孙家栋—2009年度国家最高科学技术奖"}, "answer": "D", "explanation": "于敏和孙家栋分别获得2014年度、2009年度国家最高科学技术奖。"}, {"id": 269, "chapter": "科学家精神", "stem": "下列哪项最符合科学家精神与科研规范的统一要求？", "options": {"A": "尊重证据、如实署名、开放协作并对社会负责", "B": "在证据不足时先发表阶段性结论，并在后续论文中修正", "C": "按贡献排序署名，但对关键失败数据只作内部保存", "D": "共享可复核数据，但将负面结果留待研究成熟后再披露"}, "answer": "A", "explanation": "科学家精神要求求真务实、恪守伦理规范、反对浮夸和学术不端。"}, {"id": 270, "chapter": "科学家精神", "stem": "下列科学家与技术路线对应完全正确的是？", "options": {"A": "吴文俊—稀土串级萃取；徐光宪—数学机械化；王振义—白血病诱导分化", "B": "吴文俊—数学机械化；徐光宪—稀土串级萃取；王振义—白血病诱导分化", "C": "吴文俊—数学机械化；徐光宪—白血病诱导分化；王振义—稀土串级萃取", "D": "吴文俊—白血病诱导分化；徐光宪—稀土串级萃取；王振义—数学机械化"}, "answer": "B", "explanation": "三位科学家的代表性成果依次为数学机械化、稀土串级萃取和白血病诱导分化治疗。"}, {"id": 271, "chapter": "交大校史", "stem": "上海交通大学创建于哪一年？", "options": {"A": "1895年", "B": "1897年", "C": "1896年", "D": "1905年"}, "answer": "C", "explanation": "上海交通大学创建于1896年。"}, {"id": 272, "chapter": "交大校史", "stem": "上海交通大学的前身是？", "options": {"A": "北洋大学堂", "B": "京师大学堂", "C": "山海关北洋铁路官学堂", "D": "南洋公学"}, "answer": "D", "explanation": "学校诞生于1896年，初名南洋公学。"}, {"id": 273, "chapter": "交大校史", "stem": "创办南洋公学的是？", "options": {"A": "盛宣怀", "B": "唐文治", "C": "张元济", "D": "何嗣焜"}, "answer": "A", "explanation": "盛宣怀创办南洋公学，是上海交通大学的创始人。"}, {"id": 274, "chapter": "交大校史", "stem": "上海交通大学现行校训是？", "options": {"A": "自强不息，厚德载物", "B": "饮水思源，爱国荣校", "C": "博学而笃志，切问而近思", "D": "诚朴雄伟，励学敦行"}, "answer": "B", "explanation": "学校校训为“饮水思源，爱国荣校”。"}, {"id": 275, "chapter": "交大校史", "stem": "2026年上海交通大学迎来建校多少周年？", "options": {"A": "125周年", "B": "128周年", "C": "130周年", "D": "135周年"}, "answer": "C", "explanation": "1896年至2026年为130周年。"}, {"id": 276, "chapter": "交大校史", "stem": "2005年与上海交通大学合并的是？", "options": {"A": "上海第二医科大学", "B": "上海医科大学", "C": "上海中医药大学", "D": "上海铁道医学院"}, "answer": "A", "explanation": "2005年，上海交通大学与上海第二医科大学合并。"}, {"id": 277, "chapter": "交大校史", "stem": "1999年并入上海交通大学的是？", "options": {"A": "上海第二医科大学", "B": "上海农学院", "C": "上海机械学院", "D": "上海铁道学院"}, "answer": "B", "explanation": "上海农学院于1999年并入上海交通大学。"}, {"id": 278, "chapter": "交大校史", "stem": "“南洋公学”中的“公学”主要体现其经费来源是？", "options": {"A": "主要由轮船招商局和电报局等官督商办企业经费支持", "B": "由地方官府与外国教会各承担一半", "C": "由学生缴费和校友捐赠各承担一半", "D": "半由商民捐助、半由官助"}, "answer": "D", "explanation": "学校经费半由招商局、电报局等商民捐助，半由官助，故称公学。"}, {"id": 279, "chapter": "交大校史", "stem": "上海交大的闵行校区是在哪个年代开始规划和建设的？【 】", "options": {"A": "1950年代", "B": "1960年代", "C": "1980年代", "D": "2000年代"}, "answer": "C", "explanation": "1987年，上海交大经国家批准在上海闵行区兴建闵行新校区，以满足学校的发展需要。"}, {"id": 280, "chapter": "交大校史", "stem": "南洋公学在我国近代教育史上的突出特点是？", "options": {"A": "较早形成师范、小学、中学和大学的完整教育体系", "B": "较早建立工、商、法、医并举的综合大学格局", "C": "以留学预科和实业专科为主，未设置师范与中小学层次", "D": "以大学部为核心并附设单一实业学校"}, "answer": "A", "explanation": "南洋公学是我国最早兼有师范、小学、中学和大学完整教育体系的学校之一。"}, {"id": 281, "chapter": "交大校史", "stem": "“交通大学”这一校名，最早于哪一年在交通部提交的《阁议创办交通大学提案文》中出现？", "options": {"A": "1918年", "B": "1920年", "C": "1921年", "D": "1928年"}, "answer": "B", "explanation": "1920年12月14日，叶恭绰在《拟改组交通教育呈大总统文》中写到，“兹为统一学制起见，拟将该四校校制课程，悉心厘定，分别改良，列为大学分科，而以大学总其成，名曰：交通大学。上海、北京、唐山四校悉纳入焉。”"}, {"id": 282, "chapter": "交大校史", "stem": "上海交通大学的使命是？", "options": {"A": "求真务实、开拓创新、服务国家、造福社会", "B": "传承文明、探求真理、振兴中华、造福人类", "C": "储人才、备国家之用", "D": "思源致远、创领未来"}, "answer": "B", "explanation": "学校使命为“传承文明、探求真理、振兴中华、造福人类”。"}, {"id": 283, "chapter": "交大校史", "stem": "1921年，学校合组后使用的校名是？", "options": {"A": "交通部南洋大学", "B": "国立交通大学上海本部", "C": "交通部上海工业专门学校", "D": "交通大学上海学校"}, "answer": "D", "explanation": "1921年学校成为交通大学上海学校。"}, {"id": 284, "chapter": "交大校史", "stem": "1903年7月，因受到哪一事件的牵连，导致成立仅半年多的爱国学社被迫解散？【 】", "options": {"A": "“墨水瓶事件”", "B": "拒俄运动", "C": "“《苏报》案”", "D": "“清毒”运动"}, "answer": "C", "explanation": "由于《苏报》连续发表了章太炎的《驳康有为论革命书》和邹容的《革命军》等激烈抨击清政府的文章，清政府向上海公共租界工部局提出交涉，要求查封报馆、逮捕相关人员。因为爱国学社与《苏报》的密切关系，清政府在查办《苏报》的同时，也将矛头指向了爱国学社。在巨大的政治压力下，爱国学社因受到“《苏报》案”的严重牵连，被迫于1903年7月解散。"}, {"id": 285, "chapter": "交大校史", "stem": "1910年唐文治制定的校训是？", "options": {"A": "勤、俭、敬、信", "B": "勤、慎、忠、信", "C": "诚、朴、敬、信", "D": "勤、俭、诚、勇"}, "answer": "A", "explanation": "唐文治于1910年制定“勤、俭、敬、信”四字校训。"}, {"id": 286, "chapter": "交大校史", "stem": "1928年后学校在上海使用的名称是？", "options": {"A": "交通部第一交通大学", "B": "国立交通大学（上海本部）", "C": "交通大学上海学校", "D": "国立交通大学上海分部"}, "answer": "B", "explanation": "1928年起学校称国立交通大学，上海为本部。"}, {"id": 287, "chapter": "交大校史", "stem": "日军侵入租界后，交大地下党贯彻的工作方针是？【 】", "options": {"A": "公开动员群众开展抗日游行", "B": "隐蔽精干，长期埋伏，积蓄力量，以待时机", "C": "集中力量发展党员，扩大组织规模", "D": "暂停一切活动，等待局势好转"}, "answer": "B", "explanation": "邵洛羊代表地下党学委大学区委向交大的钦湘舟提出：学习陈云《怎样做一个共产党员》一文，要党员坚定理想，遵守纪律，保守秘密，努力学习，成为群众中的模范。要积极贯彻“隐蔽精干，长期埋伏，积蓄力量，以待时机”的方针，利用社会条件所许可和群众公认的“合法”条件，开展多种形式的活动。"}, {"id": 288, "chapter": "交大校史", "stem": "抗战时期，交通大学在办学中始终坚持的学科格局是？【 】", "options": {"A": "以文科为主，理科为辅", "B": "理、工、管相结合", "C": "以工科为主，文科为辅", "D": "理、医、农相结合"}, "answer": "B", "explanation": "交大迁入法租界后，主校者、院系负责人、师资队伍基本上没有更动，学校的培养目标和教育方针都一如既往，仍以培养交通工程技术和管理人才为办学宗旨，理、工、管三院制的学科体系一直贯穿于整个抗战时期。"}, {"id": 289, "chapter": "交大校史", "stem": "抗日战争时期，国立交通大学总校一度设在？", "options": {"A": "成都", "B": "昆明", "C": "重庆", "D": "贵阳"}, "answer": "C", "explanation": "1942—1946年国立交通大学以重庆为总校。"}, {"id": 290, "chapter": "交大校史", "stem": "1921年交通大学正式合组成立时，学校分设三地，分别是上海、唐山和？【 】", "options": {"A": "南京", "B": "天津", "C": "北京", "D": "西安"}, "answer": "C", "explanation": ""}, {"id": 291, "chapter": "交大校史", "stem": "上海交通大学的英文名称是？", "options": {"A": "Shanghai Jiao Tong University", "B": "Shanghai Jiaotong University", "C": "Shanghai Chiao Tung University", "D": "Shanghai University of Communications"}, "answer": "A", "explanation": "学校章程规定英文名称为Shanghai Jiao Tong University。"}, {"id": 292, "chapter": "交大校史", "stem": "关于上海交通大学第一个党总支的组建背景与过程，下列说法正确的是【 】", "options": {"A": "1946 年 9 月，中共上海学委决定将 “临大” 交大支部、雷士德工学院及南京中央大学工学院的 15 名学生党员合并，组建交大党总支", "B": "交大党总支组建时，党员人数仅 10 余人", "C": "交大党总支直接由中共中央领导，下设 2 个分支部", "D": "1946 年 6 月全面内战爆发时，“临大” 交大分部学生党员数较抗战胜利时减少一半"}, "answer": "A", "explanation": "“1946 年 9 月，随着反‘甄审’斗争的胜利，‘临大’撤消…… 中共上海学委决定撤消‘临大’区委，‘临大’中的交大支部全体党员和雷士德工学院、南京中央大学工学院的 15 名学生党员，组织关系转入交大，合并组建交大党总支”，与选项 A 表述一致；B“到 1946 年 6 月全面内战爆发时，‘临大’交大分部的学生党员数发展到 50 多人，较抗战胜利时增加了一倍”；C“由中共上海学委领导”“下设 4个分支部”；D“增加了一倍”。"}, {"id": 293, "chapter": "交大校史", "stem": "关于上海高等实业学堂（交大前身）筹办航海专科及商船学校的过程，下列说法正确的是【 】", "options": {"A": "1909年邮传部最初决定将唐山路矿学堂改为商船学校，上海高等实业学堂仅保留铁路、电机两科", "B": "唐文治提出“代办商船学校”的两全方案，即保留铁路、电机两科，同时增设航海专科，待条件成熟再单独建商船学校", "C": "张謇为支持商船学校筹办，仅捐赠吴淞口100余亩地基，未提供资金支持", "D": "1909年 7月设立的高等船政专科（航海科）学制为 3年，全部为课堂教学，无实习环节"}, "answer": "B", "explanation": "A“邮传部于 1909年夏提出将上海高等实业学堂改为商船学校”；C“张謇慷慨解囊，捐地捐银…… 把所领的官款6万元捐给上海高等实业学堂”；D“定学制为４年，前３年学专业课程，最后1年赴轮船招商局实习”。"}, {"id": 294, "chapter": "交大校史", "stem": "交大是【 】年决定西迁的", "options": {"A": "1954", "B": "1955", "C": "1956", "D": "1857"}, "answer": "B", "explanation": "1955年中华人民共和国国务院决定将交通大学由上海迁至西安，1956年动迁。"}, {"id": 295, "chapter": "交大校史", "stem": "上海交通大学法定住所位于？", "options": {"A": "上海市东川路800号", "B": "上海市华山路1954号", "C": "上海市瑞金二路197号", "D": "上海市淮海西路125号"}, "answer": "B", "explanation": "学校章程规定法定住所为上海市华山路1954号。"}, {"id": 296, "chapter": "交大校史", "stem": "“西迁精神” 的核心是什么？", "options": {"A": "听党指挥跟党走", "B": "爱国主义", "C": "与人民同呼吸共命运", "D": "艰苦奋斗"}, "answer": "B", "explanation": "“西迁精神”的核心是爱国主义，精髓是听党指挥跟党走，与党和国家、与民族和人民同呼吸、共命运，“西迁精神”具有深刻现实意义和历史意义。坚持党对高校工作的全面领导，坚持立德树人，建设高素质教师队伍，努力培养更多一流人才。弘扬“西迁精神”，抓住新时代新机遇，到祖国最需要的地方建功立业，在新征程上创造属于我们这代人的历史功绩。"}, {"id": 297, "chapter": "交大校史", "stem": "1899年南洋公学设立的我国高校较早的出版编译机构是？", "options": {"A": "东文学堂", "B": "师范院", "C": "译书院", "D": "藏书楼"}, "answer": "C", "explanation": "南洋公学译书院是我国高校较早的出版编译机构。"}, {"id": 298, "chapter": "交大校史", "stem": "1902年爱国学社正式成立后，由谁担任首任总理？", "options": {"A": "章太炎", "B": "吴稚晖", "C": "黄炎培", "D": "蔡元培"}, "answer": "D", "explanation": "1902年11月21日，中国教育会决定建立爱国学社，以帮助这些学生继续接受教育。校址设于泥城桥福源里，蔡元培任学校总理。"}, {"id": 299, "chapter": "交大校史", "stem": "交通大学在教学制度上学习西方经验，在中国专门教育中属于创举的制度是？【 】", "options": {"A": "学年制", "B": "选科单位制度", "C": "导师制", "D": "免试入学制"}, "answer": "B", "explanation": "20年代初，交大率先实行“选科单位制度”（类似学分制），在中国教育界属于创举。"}, {"id": 300, "chapter": "交大校史", "stem": "交大学生沈家桢等人创立的“建设事业励进社（一社）””创办的第一份，也是当时极受欢迎的科普杂志是？", "options": {"A": "《大众医学》", "B": "《科学生活》", "C": "《大众农业》", "D": "《科学大众》"}, "answer": "D", "explanation": "“一社”创办的第一份杂志是《科学大众》，并大获成功。"}, {"id": 301, "chapter": "交大校史", "stem": "1908年学校设置、被认为是我国高校最早设立的相关学科是？", "options": {"A": "铁路科", "B": "商科", "C": "船政科", "D": "电机科"}, "answer": "D", "explanation": "1908年学校设置电机科，是我国高等学校最早设立的电机学科。"}, {"id": 302, "chapter": "交大校史", "stem": "在如今交大徐汇校园，保留至今的唯一一幢南洋公学时期的建筑就是【 】 ，它是当年学生学习、生活的场所。", "options": {"A": "下 院", "B": "上 院", "C": "中 院", "D": "师范院"}, "answer": "C", "explanation": "中院，1898年6月动工兴建，翌年夏完工。1899年秋季开学时，全校师生全部搬入，校外宿舍退租。"}, {"id": 303, "chapter": "交大校史", "stem": "1918年学校设置、被认为是中国现代教育史上较早的管理学科是？", "options": {"A": "铁路管理科", "B": "商科管理门", "C": "工业管理科", "D": "交通管理科"}, "answer": "A", "explanation": "1918年设置的铁路管理科被视为中国现代教育史上最早的管理学科。"}, {"id": 304, "chapter": "交大校史", "stem": "1947年，全国争取和平民主运动风起云涌，交大学生在中共地下党总支的领导下，投入爱国学生运动的洪流，成为新民主主义革命中活跃在第二条战线上的中坚力量，被誉为“【 】”。", "options": {"A": "水之源", "B": "第二条战线", "C": "中坚力量", "D": "民主堡垒"}, "answer": "D", "explanation": ""}, {"id": 305, "chapter": "交大校史", "stem": "被誉为“交通大学的缔造者”，提出“交通救国论”并担任合并后交通大学首任校长的是？【 】", "options": {"A": "唐文治", "B": "蔡元培", "C": "叶恭绰", "D": "盛宣怀"}, "answer": "C", "explanation": "1920年12月，叶恭绰向国务院会议提交《阁议创办交通大学提案文》，提议“拟以上海、唐山、北京四校，合并为交通大学”。经过数月筹备，交通大学于1921年8月1日正式成立，叶恭绰被董事会推选为校长。"}, {"id": 306, "chapter": "交大校史", "stem": "1952年，全国院系调整，交大理学院的数学、物理、化学3系的师资、设备除留下工学院教学所需之外全部调整到 ______大学，部分师资调整到华东师范大学，土木系全部调整到 ______大学。【 】", "options": {"A": "复旦 同济", "B": "同济 东华", "C": "复旦 东华", "D": "同济 大同"}, "answer": "A", "explanation": "全国院系调整，交大先后调整出数理化、土木、化工、管理、航空、水利、汽车、电讯、纺织等优势专业、师资和设备"}, {"id": 307, "chapter": "交大校史", "stem": "学校基本完成闵行校区二期建设并实现闵行战略转移是在？", "options": {"A": "1999年", "B": "2005年", "C": "2006年", "D": "2008年"}, "answer": "C", "explanation": "2006年学校基本完成闵行校区二期建设并实现战略转移。"}, {"id": 308, "chapter": "交大校史", "stem": "上海交通大学闵行校区的地址是？", "options": {"A": "上海市华山路1954号", "B": "上海市瑞金二路197号", "C": "上海市淮海西路125号", "D": "上海市东川路800号"}, "answer": "D", "explanation": "闵行校区位于上海市闵行区东川路800号。"}, {"id": 309, "chapter": "交大校史", "stem": "“饮水思源”纪念碑碑身所刻“民十九级建赠”中的“民十九级”指？", "options": {"A": "1930年入学的学生", "B": "1930届学生", "C": "1933届学生", "D": "民国十九年建校纪念班学生"}, "answer": "B", "explanation": "民国十九年即1930年，纪念碑由该届同学建赠。"}, {"id": 310, "chapter": "交大校史", "stem": "从小渔船到航空母舰，我国海上军备发展荆棘载途、阻碍重重。上世纪80年代，国家经济底子薄弱，无法满足我国造船业快速发展所需的条件。此时，一位交大人对如何发展中国造船业的问题非常关切，与我国重要领导人多次会面交流，并无条件捐赠大额资金支持祖国的发展，请问他是【 】？", "options": {"A": "李政道", "B": "包兆龙", "C": "包玉刚", "D": "陈瑞球"}, "answer": "C", "explanation": ""}, {"id": 311, "chapter": "交大校史", "stem": "徐汇校区校史博物馆馆名由哪位1947届校友题写？", "options": {"A": "钱学森", "B": "吴文俊", "C": "黄旭华", "D": "江泽民"}, "answer": "D", "explanation": "徐汇校区校史博物馆馆名由1947届校友江泽民题写。"}, {"id": 312, "chapter": "交大校史", "stem": "1930年，唐文治应邀参加交通第三十届毕业典礼，在致辞中有一段关于培养“第一等人才”的精辟论述：“须知吾人欲成学问，当为第一等学问；欲成事业，当为第一等事业；欲成人才，当为第一等人才。而欲成第一等学问、事业、人才，【 】”。", "options": {"A": "必先砥砺第一等品质", "B": "必先磨砺第一等品行", "C": "必先砥砺第一等品行", "D": "必先磨砺第一等品质"}, "answer": "C", "explanation": ""}, {"id": 313, "chapter": "交大校史", "stem": "闵行校区校史博物馆展览贯穿的主题词是？", "options": {"A": "因图强而生、因改革而兴、因人才而盛", "B": "因实业而兴、因交通而名、因改革而强", "C": "饮水思源、爱国荣校、求实创新", "D": "修品行、求学问、创事业、成人才"}, "answer": "A", "explanation": "闵行校区新馆陈展贯穿“因图强而生、因改革而兴、因人才而盛”的主题。"}, {"id": 314, "chapter": "交大校史", "stem": "唐文治对“勤、俭、敬、信”中“俭”的阐释重点是？", "options": {"A": "俭以节用，是治校的首务", "B": "俭以养廉，是立品的基础", "C": "俭以持家，是求学的前提", "D": "俭以寡欲，是治学的方法"}, "answer": "B", "explanation": "唐文治强调“俭以养廉，立品之始基也”。"}, {"id": 315, "chapter": "交大校史", "stem": "下列校名沿革按时间先后排列正确的是？", "options": {"A": "南洋公学—商部上海高等实业学堂—交通部上海工业专门学校—交通大学上海学校", "B": "南洋公学—邮传部上海高等实业学堂—商部上海高等实业学堂—交通大学上海学校", "C": "南洋公学—商部上海高等实业学堂—交通大学上海学校—交通部上海工业专门学校", "D": "商部上海高等实业学堂—南洋公学—交通部上海工业专门学校—交通大学上海学校"}, "answer": "A", "explanation": "四个校名对应起始年份依次为1896、1905、1912、1921。"}, {"id": 316, "chapter": "交大校史", "stem": "下列校史事件与年份对应完全正确的是？", "options": {"A": "1896年南洋公学创办；1959年定名上海交通大学；1999年与上海第二医科大学合并", "B": "1896年南洋公学创办；1959年定名上海交通大学；2005年与上海第二医科大学合并", "C": "1896年南洋公学创办；1956年定名上海交通大学；2005年并入上海农学院", "D": "1905年南洋公学创办；1959年定名上海交通大学；2005年与上海第二医科大学合并"}, "answer": "B", "explanation": "三项关键校史节点分别对应1896年、1959年和2005年。"}, {"id": 317, "chapter": "交大校史", "stem": "下列关于交大校史文化的表述正确的是？", "options": {"A": "现行校训为'饮水思源，爱国荣校'，'饮水思源'纪念碑建成于1919年", "B": "1910年唐文治制定'勤、俭、敬、信'校训，学校沿用至今未作调整", "C": "现行校训是“饮水思源，爱国荣校”，1910年唐文治曾制定“勤、俭、敬、信”校训", "D": "现行校训为'饮水思源，爱国荣校'，校史博物馆首次开馆于2005年"}, "answer": "C", "explanation": "现行校训与历史校训均有官方校史依据；纪念碑建于1933年，博物馆始建于1996年。"}, {"id": 318, "chapter": "交大校史", "stem": "下列关于闵行校区发展的表述正确的是？", "options": {"A": "1987年迎来首批新生，1999年基本完成闵行战略转移", "B": "1996年迎来首批新生，2006年与上海第二医科大学合并", "C": "1987年开始规划建设，2021年首次成为学校主要办学基地", "D": "1987年迎来首批2600多名新生，2006年基本完成战略转移"}, "answer": "D", "explanation": "闵行校区1987年迎来首批新生，2006年基本完成二期建设和战略转移。"}];
